-- HD2-Addon: mods/keg/byog
-- BYOG (Balance Your Own Game): changes the values of weapons, throwables, stratagems, backpacks,
-- shields and vehicles in the game's memory, from an in-game menu and a config file.
-- Files, all in %LOCALAPPDATA%\BYOG:
--   config.txt    what to change (see docs/CONFIG-FORMAT.md; a template is created on first run)
--   presets\      what was set in the in-game menu, one file a preset (wins over config.txt)
--   settings.txt  the menu's keys, language and active preset
--   STATUS.txt    what happened: first line is the verdict
--   catalog.txt   every item and stat this build knows, with the game's value and allowed range
--   byog.log      developer log
--   RESEARCH.txt  v1.1.1 only: rows of the game's status table and engine facts, for the next version
-- Requires Bingus Shared Loader (API 1). Runs on LuaJIT (Lua 5.1 syntax only).
--
-- Safety rules this file implements:
--   * nothing is written unless the game executable and game.dll hash to a verified build;
--   * every write is range-checked before, done through the OS (never a raw pointer), read back
--     with an independent decoder, and undone when the config no longer asks for it;
--   * the game keeps its component tables in read-only pages: such a page is made writable for
--     the one 4-byte write and put back to read-only at once (checked);
--   * tables are located by 'LDLD' + version + type hash only; counts and layouts are derived;
--   * all work is sliced: at most FRAME_BUDGET seconds on every STEP_EVERY-th frame.

local MOD = {
    title = 'BYOG', version = '@@VERSION@@', global = 'BYOG',
    dir = 'BYOG', status = 'STATUS.txt', log = 'byog.log', config = 'config.txt',
    catalog = 'catalog.txt',
}
-- Generated by tools/gen_tuner_data.py: verified builds (V), tables (T), items (I), fields (F),
-- ranges (R), aliases (A), takeovers (O), stock rows (W), attachment values (X), row indexes (N).
local DATA = [==[
@@DATA@@]==]

if rawget(_G, MOD.global) then return end

-- ---------------------------------------------------------------- tuning
local START_FRAME = 120          -- let the game start before touching anything
local STEP_EVERY = 2             -- heavy work on every 2nd frame only
local FRAME_BUDGET = 0.001       -- seconds of work per working frame
local RECHECK_SECONDS = 5        -- read back every applied value this often
local RELOAD_DEBOUNCE = 0.75     -- seconds: further presses of the reload key within this time are ignored
local SEARCH_BACKOFF = { 5, 10, 20, 30 }   -- seconds between searches while tables are missing
local DEFAULT_RESCAN_SECONDS = 120          -- look for new copies of patched tables this often
local MAX_BLOCK = 0x10000000
local ADDRESS_START, ADDRESS_END = 0x10000, 0x7FFFFFFF0000
local LDLD = 0x444C444C          -- 'LDLD' read as a little-endian u32
local PAGE_READONLY, PAGE_READWRITE = 0x02, 0x04
local FILE_CHUNK = 262144
local HASH_CHUNK = 65536         -- bytes hashed per step while checking the build

local state = {
    title = MOD.title, version = MOD.version, phase = 'starting', verdict = 'WAITING',
    frame = 0, errors = 0, writes = 0, restores = 0, rewrites = 0, passes = 0, unlocks = 0, left_open = 0,
    reloads = 0,
    worst_frame = 0, busy_frames = 0, busy_seconds = 0,
}
rawset(_G, MOD.global, state)

-- ---------------------------------------------------------------- log
local log_lines, log_seen, log_dirty = {}, {}, false
local function log(message)
    message = tostring(message)
    local n = (log_seen[message] or 0) + 1
    log_seen[message] = n
    if n > 3 or #log_lines >= 4000 then return end
    if n == 3 then message = message .. ' (further repeats not logged)' end
    log_lines[#log_lines + 1] = '[frame ' .. state.frame .. '] ' .. message
    log_dirty = true
end

-- Addresses do not fit a 32-bit %X; print the two halves.
local function hex(n)
    local high = math.floor(n / 4294967296)
    if high > 0 then return string.format('0x%X%08X', high, n - high * 4294967296) end
    return string.format('0x%X', n)
end

local function trim(text) return (text:gsub('^%s+', ''):gsub('%s+$', '')) end

-- ---------------------------------------------------------------- numbers
-- Independent IEEE-754 decoder: read-back checks never share code with the encoder.
local function bits_to_f32(bits)
    local sign = 1
    if bits >= 2147483648 then sign = -1; bits = bits - 2147483648 end
    local exponent = math.floor(bits / 8388608)
    local mantissa = bits - exponent * 8388608
    if exponent == 255 then
        if mantissa == 0 then return sign * math.huge end
        return 0 / 0
    end
    if exponent == 0 then return sign * mantissa * 2 ^ -149 end
    return sign * (1 + mantissa / 8388608) * 2 ^ (exponent - 127)
end

local function close_enough(a, b)
    if a ~= a or b ~= b then return false end
    return math.abs(a - b) <= 0.00001 * math.max(1, math.abs(b))
end

local function same_value(storage, a, b)
    if a == nil or b == nil then return false end
    if storage == 'f32' then return close_enough(a, b) end
    return a == b
end

local function show(value, storage)
    if value == nil then return '?' end
    if storage == 'f32' then
        local text = string.format('%.4f', value):gsub('0+$', ''):gsub('%.$', '')
        return text
    end
    return string.format('%.0f', value)
end

-- ---------------------------------------------------------------- windows api
local ffi_ok, ffi = pcall(require, 'ffi')
local A = nil

local function build_api()
    local a = {}
    local cvoid = ffi.typeof('const void *')
    local void = ffi.typeof('void *')

    -- Every function is fetched by name and cast to OUR signature, so declarations made by
    -- other addons can never change how we call it. Tests inject their own resolver.
    local resolve = rawget(_G, 'HD2ST_TEST_RESOLVER')
    if type(resolve) ~= 'function' then
        for _, declaration in ipairs({
            'void *GetModuleHandleA(const char *name);',
            'void *LoadLibraryA(const char *name);',
            'void *GetProcAddress(void *module, const char *name);',
        }) do pcall(ffi.cdef, declaration) end
        local k32 = ffi.load('kernel32')
        local get_module = ffi.cast('void *(*)(const char *)', k32.GetModuleHandleA)
        local load_library = ffi.cast('void *(*)(const char *)', k32.LoadLibraryA)
        local get_proc = ffi.cast('void *(*)(void *, const char *)', k32.GetProcAddress)
        resolve = function(dll, name, signature)
            local module = get_module(dll)
            if module == nil then module = load_library(dll) end
            if module == nil then error('cannot load ' .. dll) end
            local address = get_proc(module, name)
            if address == nil then error(name .. ' not found in ' .. dll) end
            return ffi.cast(signature, address)
        end
    end
    local K = 'kernel32.dll'
    local get_process = resolve(K, 'GetCurrentProcess', 'void *(*)(void)')
    local get_process_id = resolve(K, 'GetCurrentProcessId', 'uint32_t (*)(void)')
    local read_memory = resolve(K, 'ReadProcessMemory', 'int (*)(void *, const void *, void *, size_t, size_t *)')
    local write_memory = resolve(K, 'WriteProcessMemory', 'int (*)(void *, void *, const void *, size_t, size_t *)')
    local virtual_query = resolve(K, 'VirtualQuery', 'size_t (*)(const void *, void *, size_t)')
    local virtual_protect = resolve(K, 'VirtualProtect', 'int (*)(void *, size_t, uint32_t, uint32_t *)')
    local virtual_alloc = resolve(K, 'VirtualAlloc', 'void *(*)(void *, size_t, uint32_t, uint32_t)')
    local working_set = resolve(K, 'K32QueryWorkingSetEx', 'int (*)(void *, void *, uint32_t)')
    local create_directory = resolve(K, 'CreateDirectoryA', 'int (*)(const char *, void *)')
    local get_last_error = resolve(K, 'GetLastError', 'uint32_t (*)(void)')
    local find_first = resolve(K, 'FindFirstFileA', 'void *(*)(const char *, void *)')
    local find_next = resolve(K, 'FindNextFileA', 'int (*)(void *, void *)')
    local find_close = resolve(K, 'FindClose', 'int (*)(void *)')
    local perf_counter = resolve(K, 'QueryPerformanceCounter', 'int (*)(int64_t *)')
    local perf_frequency = resolve(K, 'QueryPerformanceFrequency', 'int (*)(int64_t *)')
    local module_handle = resolve(K, 'GetModuleHandleA', 'void *(*)(const char *)')
    local module_file_name = resolve(K, 'GetModuleFileNameA', 'uint32_t (*)(void *, char *, uint32_t)')
    local create_file = resolve(K, 'CreateFileA',
        'void *(*)(const char *, uint32_t, uint32_t, void *, uint32_t, uint32_t, void *)')
    local read_file = resolve(K, 'ReadFile', 'int (*)(void *, void *, uint32_t, uint32_t *, void *)')
    local file_size = resolve(K, 'GetFileSizeEx', 'int (*)(void *, int64_t *)')
    local close_handle = resolve(K, 'CloseHandle', 'int (*)(void *)')
    local query_memory = resolve('ntdll.dll', 'NtQueryVirtualMemory',
        'int32_t (*)(void *, const void *, int32_t, void *, size_t, size_t *)')
    local U = 'user32.dll'
    local key_state = resolve(U, 'GetAsyncKeyState', 'int16_t (*)(int32_t)')
    local foreground_window = resolve(U, 'GetForegroundWindow', 'void *(*)(void)')
    local window_process = resolve(U, 'GetWindowThreadProcessId', 'uint32_t (*)(void *, uint32_t *)')

    local process = get_process()
    local got = ffi.new('size_t[1]')

    local ticks, frequency = ffi.new('int64_t[1]'), ffi.new('int64_t[1]')
    perf_frequency(frequency)
    local per_second = tonumber(frequency[0])
    if not per_second or per_second <= 0 then error('no performance counter') end
    function a.now()
        perf_counter(ticks)
        return tonumber(ticks[0]) / per_second
    end

    -- The allocation holding `address`: base, size, true. For free memory: base, size, false.
    -- NtQueryVirtualMemory's region information costs the same for any allocation size;
    -- VirtualQuery is only used for free memory (in-game it took 9.9 ms on one huge region).
    local info = ffi.new('uint64_t[6]')
    local info32 = ffi.cast('uint32_t *', info)
    local returned = ffi.new('size_t[1]')
    function a.allocation(address)
        local pointer = ffi.cast(cvoid, address)
        if query_memory(process, pointer, 3, info, 48, returned) == 0
            or query_memory(process, pointer, 3, info, 32, returned) == 0 then
            local base, size = tonumber(info[0]), tonumber(info[2])
            if base and size and size > 0 and base <= address then return base, size, true end
        end
        if tonumber(virtual_query(pointer, info, 48)) ~= 48 then return nil end
        local base, size = tonumber(info[0]), tonumber(info[3])
        if not base or not size or size <= 0 then return nil end
        -- state at +32: MEM_FREE 0x10000. Anything else here means region information is not
        -- available on this system; treat the region as one allocation.
        return base, size, info32[8] ~= 0x10000
    end

    -- One page: present in memory?, its protection, shared (mapped) or private.
    local page = ffi.new('uint64_t[2]')
    function a.page(address)
        page[0], page[1] = address - address % 4096, 0
        if working_set(process, page, 16) == 0 then return false end
        local attributes = tonumber(page[1] % 65536)
        if attributes % 2 ~= 1 then return false end
        return true, math.floor(attributes / 16) % 2048, attributes >= 32768
    end
    -- For `count` pages (at most 64) from the page-aligned `address`: true where the page is present
    -- in memory, private and readable. Only such pages are ever read by the probe.
    local page_set, usable = ffi.new('uint64_t[128]'), {}
    function a.pages(address, count)
        for k = 0, count - 1 do page_set[2 * k], page_set[2 * k + 1] = address + k * 4096, 0 end
        if working_set(process, page_set, count * 16) == 0 then return nil end
        for k = 0, count - 1 do
            local attributes = tonumber(page_set[2 * k + 1] % 65536)
            local protection = math.floor(attributes / 16) % 2048
            usable[k + 1] = attributes % 2 == 1 and attributes < 32768
                and (protection == PAGE_READWRITE or protection == PAGE_READONLY)
        end
        usable[count + 1] = false
        return usable
    end
    -- The region holding `address` as VirtualQuery reports it (MEMORY_BASIC_INFORMATION).
    function a.region(address)
        if tonumber(virtual_query(ffi.cast(cvoid, address), info, 48)) ~= 48 then return nil end
        return { base = tonumber(info[0]), allocation = tonumber(info[1]), size = tonumber(info[3]),
                 state = tonumber(info32[8]), protection = tonumber(info32[9]), type = tonumber(info32[10]) }
    end
    function a.readable_private(address)
        local present, protection, shared = a.page(address)
        return present and not shared and (protection == PAGE_READWRITE or protection == PAGE_READONLY)
    end
    -- The first page of an allocation. A page the system has taken out of the working set (the game has
    -- not touched it for a while) says nothing through a.page; in game this hid whole chains of tables
    -- ("waiting for their table" in a running mission, v0.12.0 and v0.14.0). For a large allocation the
    -- region is asked instead: committed, private and readable is enough, reading brings the page back.
    function a.readable_start(address, size)
        local present, protection, shared = a.page(address)
        if present then
            return not shared and (protection == PAGE_READWRITE or protection == PAGE_READONLY)
        end
        if size < 65536 then return false end
        local r = a.region(address)
        return r ~= nil and r.state == 0x1000 and r.type == 0x20000
            and (r.protection == PAGE_READWRITE or r.protection == PAGE_READONLY)
    end

    a.buffer_size = FILE_CHUNK + 16
    a.buffer = ffi.new('uint8_t[?]', a.buffer_size)
    a.words = ffi.cast('uint32_t *', a.buffer)
    a.buffer_address = tonumber(ffi.cast('uintptr_t', a.buffer))
    function a.read(address, size)
        if size <= 0 or size > a.buffer_size then return false end
        if read_memory(process, ffi.cast(cvoid, address), a.buffer, size, got) == 0 then return false end
        return tonumber(got[0]) == size
    end

    local cell = ffi.new('uint32_t[2]')
    function a.u32(address)
        if read_memory(process, ffi.cast(cvoid, address), cell, 4, got) == 0 then return nil end
        if tonumber(got[0]) ~= 4 then return nil end
        return tonumber(cell[0])
    end
    function a.u64(address)
        if read_memory(process, ffi.cast(cvoid, address), cell, 8, got) == 0 then return nil end
        if tonumber(got[0]) ~= 8 then return nil end
        return tonumber(cell[0]) + tonumber(cell[1]) * 4294967296
    end

    -- The only function in this file that changes game memory: 4 bytes, through the OS.
    local out = ffi.new('uint32_t[1]')
    function a.write_u32(address, bits)
        out[0] = bits
        if write_memory(process, ffi.cast(void, address), out, 4, got) == 0 then return false end
        return tonumber(got[0]) == 4
    end

    -- Changes the protection of the one page holding `address`. -> true when Windows accepted it.
    local old_protection = ffi.new('uint32_t[1]')
    function a.protect(address, protection)
        return virtual_protect(ffi.cast(void, address - address % 4096), 4096, protection, old_protection) ~= 0
    end

    -- New read-write memory of our own at exactly `address` (which must be free). -> address, or nil
    function a.alloc(address, size)
        local got = virtual_alloc(ffi.cast(void, address), size, 0x3000, PAGE_READWRITE)   -- reserve + commit
        if got == nil then return nil end
        return tonumber(ffi.cast('uintptr_t', got))
    end

    -- f32 -> bit pattern, by copying the bytes of a float (no pointer aliasing).
    local float_cell, bits_cell = ffi.new('float[1]'), ffi.new('uint32_t[1]')
    function a.f32_bits(value)
        float_cell[0] = value
        ffi.copy(bits_cell, float_cell, 4)
        return tonumber(bits_cell[0])
    end

    function a.mkdir(path)
        return create_directory(path, nil) ~= 0 or get_last_error() == 183
    end

    -- The names of the files matching a pattern like C:\folder\*.txt (folders are left out).
    -- WIN32_FIND_DATAA: attributes at +0, the name at +44 (260 bytes); 320 bytes in all.
    local found = ffi.new('uint8_t[328]')
    function a.list(pattern)
        local names = {}
        local handle = find_first(pattern, found)
        if handle == nil or tonumber(ffi.cast('intptr_t', handle)) == -1 then return names end
        repeat
            if math.floor(tonumber(ffi.cast('uint32_t *', found)[0]) / 16) % 2 == 0 then   -- not a folder
                names[#names + 1] = ffi.string(ffi.cast('const char *', found) + 44)
            end
        until find_next(handle, found) == 0 or #names >= 200
        find_close(handle)
        return names
    end

    function a.module(name)
        local handle = module_handle(name)
        if handle == nil then return nil end
        local path_buffer = ffi.new('char[1024]')
        local length = module_file_name(handle, path_buffer, 1024)
        return tonumber(ffi.cast('uintptr_t', handle)), length > 0 and ffi.string(path_buffer, length) or nil
    end
    -- File path of the module loaded at `base`, or nil when no module starts there.
    function a.module_file(base)
        local path_buffer = ffi.new('char[1024]')
        local length = module_file_name(ffi.cast(void, base), path_buffer, 1024)
        return length > 0 and ffi.string(path_buffer, length) or nil
    end
    function a.open(path)
        local handle = create_file(path, 0x80000000, 7, nil, 3, 0x08000000, nil)
        if handle == nil or tonumber(ffi.cast('intptr_t', handle)) == -1 then return nil end
        local size = ffi.new('int64_t[1]')
        if file_size(handle, size) == 0 then close_handle(handle); return nil end
        return handle, tonumber(size[0])
    end
    local file_got = ffi.new('uint32_t[1]')
    function a.read_file(handle)
        if read_file(handle, a.buffer, HASH_CHUNK, file_got, nil) == 0 then return nil end
        return tonumber(file_got[0])
    end
    function a.close(handle) close_handle(handle) end

    local B = 'bcrypt.dll'
    local open_algorithm = resolve(B, 'BCryptOpenAlgorithmProvider',
        'int32_t (*)(void **, const uint16_t *, const uint16_t *, uint32_t)')
    local close_algorithm = resolve(B, 'BCryptCloseAlgorithmProvider', 'int32_t (*)(void *, uint32_t)')
    local create_hash = resolve(B, 'BCryptCreateHash',
        'int32_t (*)(void *, void **, uint8_t *, uint32_t, uint8_t *, uint32_t, uint32_t)')
    local hash_data = resolve(B, 'BCryptHashData', 'int32_t (*)(void *, uint8_t *, uint32_t, uint32_t)')
    local finish_hash = resolve(B, 'BCryptFinishHash', 'int32_t (*)(void *, uint8_t *, uint32_t, uint32_t)')
    local destroy_hash = resolve(B, 'BCryptDestroyHash', 'int32_t (*)(void *)')
    local sha256_name = ffi.new('uint16_t[7]', { 83, 72, 65, 50, 53, 54, 0 })   -- L"SHA256"
    function a.sha256_begin()
        local algorithm, hash = ffi.new('void *[1]'), ffi.new('void *[1]')
        if open_algorithm(algorithm, sha256_name, nil, 0) ~= 0 then return nil end
        if create_hash(algorithm[0], hash, nil, 0, nil, 0, 0) ~= 0 then
            close_algorithm(algorithm[0], 0)
            return nil
        end
        return { algorithm = algorithm[0], hash = hash[0] }
    end
    function a.sha256_update(context, size) return hash_data(context.hash, a.buffer, size, 0) == 0 end
    function a.sha256_finish(context)
        local digest = ffi.new('uint8_t[32]')
        local ok = finish_hash(context.hash, digest, 32, 0) == 0
        destroy_hash(context.hash)
        close_algorithm(context.algorithm, 0)
        if not ok then return nil end
        local parts = {}
        for i = 0, 31 do parts[i + 1] = string.format('%02X', digest[i]) end
        return table.concat(parts)
    end

    -- keyboard: is the key down right now, and is the game the window in front?
    local own_process, window_owner = get_process_id(), ffi.new('uint32_t[1]')
    function a.key_down(vk) return key_state(vk) < 0 end
    function a.game_in_front()
        local window = foreground_window()
        if window == nil then return false end
        window_owner[0] = 0
        window_process(window, window_owner)
        return window_owner[0] == own_process
    end

    -- Raw input: what the process registered for (RAWINPUTDEVICE: u16 usage page, u16 usage, u32 flags,
    -- window handle; 16 bytes), and registering a list of such entries (flags 1 = remove).
    local raw_get = resolve(U, 'GetRegisteredRawInputDevices', 'uint32_t (*)(void *, uint32_t *, uint32_t)')
    local raw_set = resolve(U, 'RegisterRawInputDevices', 'int (*)(const void *, uint32_t, uint32_t)')
    local raw_buffer, raw_count = ffi.new('uint8_t[512]'), ffi.new('uint32_t[1]')
    function a.raw_devices()
        raw_count[0] = 32
        local n = raw_get(raw_buffer, raw_count, 16)
        if n == 0xFFFFFFFF or n > 32 then return nil end
        local words, list = ffi.cast('uint16_t *', raw_buffer), {}
        for i = 0, n - 1 do
            list[i + 1] = { page = words[i * 8], usage = words[i * 8 + 1],
                            flags = tonumber(ffi.cast('uint32_t *', raw_buffer)[i * 4 + 1]),
                            window = tonumber(ffi.cast('uint64_t *', raw_buffer)[i * 2 + 1]) }
        end
        return list
    end
    function a.raw_register(list)
        if #list == 0 or #list > 32 then return false end
        ffi.fill(raw_buffer, 512)
        for i, d in ipairs(list) do
            ffi.cast('uint16_t *', raw_buffer)[(i - 1) * 8] = d.page
            ffi.cast('uint16_t *', raw_buffer)[(i - 1) * 8 + 1] = d.usage
            ffi.cast('uint32_t *', raw_buffer)[(i - 1) * 4 + 1] = d.flags
            ffi.cast('uint64_t *', raw_buffer)[(i - 1) * 2 + 1] = d.window
        end
        return raw_set(raw_buffer, #list, 16) ~= 0
    end

    -- The game's window (the one in front, when it is ours), whether this thread owns it, and its thread.
    local current_thread = resolve(K, 'GetCurrentThreadId', 'uint32_t (*)(void)')
    local function handle(p) return tonumber(ffi.cast('uintptr_t', p)) end
    -- The mouse pointer inside a window: x, y from the top left corner of what the window shows, and the
    -- width and height of that.
    local cursor_pos = resolve(U, 'GetCursorPos', 'int (*)(void *)')
    local to_client = resolve(U, 'ScreenToClient', 'int (*)(void *, void *)')
    local client_rect = resolve(U, 'GetClientRect', 'int (*)(void *, void *)')
    local point, rect_ = ffi.new('int32_t[2]'), ffi.new('int32_t[4]')
    function a.mouse(window)
        if cursor_pos(point) == 0 or to_client(ffi.cast(void, window), point) == 0 then return nil end
        if client_rect(ffi.cast(void, window), rect_) == 0 then return nil end
        return point[0], point[1], rect_[2], rect_[3]
    end
    function a.game_window()
        local window = foreground_window()
        if window == nil then return nil end
        window_owner[0] = 0
        local thread = window_process(window, window_owner)
        if window_owner[0] ~= own_process then return nil end
        return handle(window), thread == current_thread(), thread
    end

    -- ---- the message filter
    -- Windows calls a "get message" hook on a thread for every message that thread takes off its queue:
    --     LRESULT proc(int code, WPARAM wParam, LPARAM lParam)        lParam: the MSG (its message at +8)
    -- The code below is that function. While the byte at `flag` is not 0 it turns WM_KEYDOWN (0x100) and
    -- WM_CHAR (0x102) into WM_NULL (0), which is the way Windows gives for dropping a message there; a
    -- key that is released (WM_KEYUP) is let through, so a key held when the menu opens does not stay
    -- "down" for the game. Then it goes on to CallNextHookEx(NULL, code, wParam, lParam), as a hook must.
    --      0  85 C9                     test ecx, ecx            ; code < 0: hands off
    --      2  78 29                     js   pass
    --      4  48 B8 <flag>              mov  rax, flag
    --     14  80 38 00                  cmp  byte [rax], 0       ; the menu is closed
    --     17  74 1A                     je   pass
    --     19  41 8B 40 08               mov  eax, [r8 + 8]       ; MSG.message
    --     23  3D 00 01 00 00            cmp  eax, 0x100
    --     28  74 07                     je   drop
    --     30  3D 02 01 00 00            cmp  eax, 0x102
    --     35  75 08                     jne  pass
    --     37  41 C7 40 08 00 00 00 00   drop: mov dword [r8 + 8], 0
    --     45  4D 89 C1                  pass: mov r9, r8         ; lParam
    --     48  49 89 D0                  mov  r8, rdx             ; wParam
    --     51  48 63 D1                  movsxd rdx, ecx          ; code
    --     54  31 C9                     xor  ecx, ecx            ; hook handle: not used by Windows
    --     56  48 B8 <CallNextHookEx>    mov  rax, CallNextHookEx
    --     66  FF E0                     jmp  rax
    local function u64_bytes(n)
        local out = {}
        for i = 1, 8 do
            out[i] = string.char(n % 256)
            n = math.floor(n / 256)
        end
        return table.concat(out)
    end
    function a.hook_code(flag, next_hook)
        return '\x85\xC9' .. '\x78\x29' .. '\x48\xB8' .. u64_bytes(flag) .. '\x80\x38\x00' .. '\x74\x1A'
            .. '\x41\x8B\x40\x08' .. '\x3D\x00\x01\x00\x00' .. '\x74\x07' .. '\x3D\x02\x01\x00\x00' .. '\x75\x08'
            .. '\x41\xC7\x40\x08\x00\x00\x00\x00' .. '\x4D\x89\xC1' .. '\x49\x89\xD0' .. '\x48\x63\xD1' .. '\x31\xC9'
            .. '\x48\xB8' .. u64_bytes(next_hook) .. '\xFF\xE0'
    end
    local set_hook = resolve(U, 'SetWindowsHookExA', 'void *(*)(int, void *, void *, uint32_t)')
    local call_next = resolve(U, 'CallNextHookEx', 'intptr_t (*)(void *, int, uintptr_t, intptr_t)')
    -- two pieces of memory of our own, anywhere: they are never given back, so the filter stays valid
    -- for as long as the process lives, whatever happens to this script
    local function own_memory()
        local got = virtual_alloc(ffi.cast(void, 0), 4096, 0x3000, PAGE_READWRITE)
        local n = 0
        while got == nil and n < 64 do                       -- (a fixed place, where "anywhere" is not offered)
            got = virtual_alloc(ffi.cast(void, 0x6F0000000000 + n * 0x10000), 4096, 0x3000, PAGE_READWRITE)
            n = n + 1
        end
        return got ~= nil and handle(got) or nil
    end
    local hook = nil                                          -- { flag = address, thread = id }
    -- Puts the filter on a thread of this process, once. -> true, or nil and why not
    function a.hook_install(thread)
        if hook then
            if hook.thread == thread then return true end
            return nil, 'the filter is on another thread'
        end
        local code_at, flag_at = own_memory(), own_memory()
        if not code_at or not flag_at then return nil, 'no memory' end
        local code = a.hook_code(flag_at, handle(call_next))
        code = code .. string.rep('\xCC', (4 - #code % 4) % 4)
        for i = 1, #code, 4 do
            local b1, b2, b3, b4 = code:byte(i, i + 3)
            if not a.write_u32(code_at + i - 1, b1 + b2 * 256 + b3 * 65536 + b4 * 16777216) then
                return nil, 'the code could not be written'
            end
        end
        if not a.write_u32(flag_at, 0) then return nil, 'the flag could not be written' end
        if not a.protect(code_at, 0x20) then return nil, 'the code could not be made executable' end   -- execute + read
        local got = set_hook(3, ffi.cast(void, code_at), nil, thread)                                   -- WH_GETMESSAGE
        if got == nil then return nil, 'Windows refused the hook (error ' .. tostring(get_last_error()) .. ')' end
        hook = { flag = flag_at, thread = thread, code = code_at }
        return true, code_at
    end
    -- while on, the filter drops the key messages; off, it passes everything
    function a.hook_on(on)
        if not hook then return false end
        return a.write_u32(hook.flag, on and 1 or 0)
    end
    -- Windows' own word on whether a window's thread has stopped taking its messages
    local is_hung = resolve(U, 'IsHungAppWindow', 'int (*)(void *)')
    function a.window_hung(window) return is_hung(ffi.cast(void, window)) ~= 0 end

    return a
end

-- ---------------------------------------------------------------- files
local out_dir = nil
local function ensure_out_dir()
    if out_dir then return out_dir end
    local base = os.getenv('LOCALAPPDATA')
    if not base or base == '' then return nil end
    local dir = base .. '\\' .. MOD.dir
    if A then pcall(A.mkdir, dir) end
    out_dir = dir
    return dir
end

-- Writes into our own folder; when that is impossible, into the loader's log folder.
local function write_file(name, text)
    local ok = pcall(function()
        local base = os.getenv('LOCALAPPDATA')
        local dir = ensure_out_dir()
        local handle = dir and io.open(dir .. '\\' .. name, 'wb')
        if not handle and base then
            handle = io.open(base .. '\\CowboyBingus\\Helldivers2\\Logs\\' .. MOD.dir .. '-' .. name, 'wb')
        end
        if not handle then return end
        handle:write(text)
        handle:close()
    end)
    return ok
end

local function read_file(name)
    local dir = ensure_out_dir()
    if not dir then return nil end
    local handle = io.open(dir .. '\\' .. name, 'rb')
    if not handle then return nil end
    local text = handle:read('*a')
    handle:close()
    return text
end

local function flush_log()
    log_dirty = false
    write_file(MOD.log, MOD.title .. ' v' .. MOD.version .. '\r\n'
        .. 'phase: ' .. state.phase .. '   errors: ' .. state.errors .. '\r\n\r\n'
        .. table.concat(log_lines, '\r\n') .. '\r\n')
end

-- ---------------------------------------------------------------- cooperative scheduling
local deadline = 0
local function pause()
    if A.now() >= deadline then coroutine.yield() end
end

-- ---------------------------------------------------------------- generated data
local BUILDS = {}                                    -- { label, exe, dll }
local SPECS, SPEC_BY_TYPE, SPEC_ORDER = {}, {}, {}   -- tables
local ITEMS, ITEM_BY_NAME = {}, {}                   -- index -> item; 'category:name' -> item
local FIELDS = {}                                    -- field key -> field (shared between items)
local RANGES, ALIASES = {}, {}
local ROWS = {}                                      -- 'table|row id' -> stock bytes as hex (takeovers)
local INDEXES = {}                                   -- 'build label|table' -> { rva, slots } inside game.dll
local MAGAZINES = {}                                 -- attachment resource -> items carrying it by default
local SPARE, LIVE_WORDS = {}, {}                     -- rows to borrow; words copied from memory
local field_count = 0

-- little-endian u32 at byte offset `offset` of a hex string
local function hex_word(text, offset)
    local a, b, c, d = text:sub(offset * 2 + 1, offset * 2 + 2), text:sub(offset * 2 + 3, offset * 2 + 4),
        text:sub(offset * 2 + 5, offset * 2 + 6), text:sub(offset * 2 + 7, offset * 2 + 8)
    return tonumber(a, 16) + tonumber(b, 16) * 256 + tonumber(c, 16) * 65536 + tonumber(d, 16) * 16777216
end

local function field_key(table_name, key, offset) return table_name .. '|' .. key .. '|' .. offset end

local function parse_data()
    local count = 0
    -- Read straight out of the one big string: no string per line, and no copy of it. Sixty thousand
    -- strings thrown away at once made the interpreter's table of strings grow and shrink in one piece,
    -- a 20 ms frame (v2.0.0, measured offline).
    -- The collector rests meanwhile. A collection that finishes while the big tables are still being
    -- filled has to walk, in one piece, everything added to them since it marked them: one line then cost
    -- a 10 - 15 ms frame (v2.0.0, measured offline). Started when the data is in, it finds them at rest.
    collectgarbage('stop')
    local f, had = {}, 0
    local at, size = 1, #DATA
    while at <= size do
        local stop = DATA:find('\n', at, true) or size + 1
        local n = 0
        while at <= stop do
            local bar = DATA:find('|', at, true)
            if not bar or bar > stop then bar = stop end
            n = n + 1
            f[n] = DATA:sub(at, bar - 1)
            at = bar + 1
        end
        for k = n + 1, had do f[k] = nil end
        had = n
        local kind = f[1]
        if kind == 'V' then
            BUILDS[#BUILDS + 1] = { label = f[2], exe = f[3], dll = f[4] }
        elseif kind == 'T' then
            local spec = { name = f[2], type = tonumber(f[3], 16), shape = f[4],
                           stride = tonumber(f[5]), id_at = tonumber(f[6]), blocks = {} }
            SPECS[spec.name], SPEC_BY_TYPE[spec.type] = spec, spec
            SPEC_ORDER[#SPEC_ORDER + 1] = spec.name
        elseif kind == 'I' then
            local item = { index = tonumber(f[2]), category = f[3], name = f[4], entity = f[5],
                           display = f[6] ~= '' and f[6] or nil, stats = {}, stat_order = {} }
            ITEMS[item.index] = item
            ITEM_BY_NAME[item.category .. ':' .. item.name:lower()] = item
        elseif kind == 'K' then
            -- something the tables do not hold, shown beside the game's value (a reload's length, from the wiki)
            local item = ITEMS[tonumber(f[2])]
            item.hints = item.hints or {}
            item.hints[f[3]] = f[4]
        elseif kind == 'J' then
            -- the menu shows the items of a group as one row (a Hunter: its bodies, its claws)
            local item = ITEMS[tonumber(f[2])]
            item.group, item.section, item.section_order = f[3], f[4], tonumber(f[5])
        elseif kind == 'F' then
            local item = ITEMS[tonumber(f[2])]
            local key = field_key(f[4], f[5], tonumber(f[6]))
            local field = FIELDS[key]
            if not field then
                field = { key = key, table = f[4], record = f[5], offset = tonumber(f[6]), storage = f[7],
                          stock = tonumber(f[8]), users = {} }
                FIELDS[key] = field
                field_count = field_count + 1
            end
            field.users[#field.users + 1] = item.name .. '.' .. f[3]
            -- one record per block (armor kits, armor passives): nothing but the game's own number is
            -- ever overwritten there, so that what another mod has changed is left alone
            if SPECS[f[4]] and SPECS[f[4]].shape == 'S' then field.exact = true end
            if f[9] == 'M' then
                -- one more place of a value the game keeps several times (an armor's weight: once per piece)
                local entry = item.stats[f[3]]
                entry.more = entry.more or {}
                entry.more[#entry.more + 1] = field
            else
                if not item.stats[f[3]] then item.stat_order[#item.stat_order + 1] = f[3] end
                item.stats[f[3]] = { field = field, attachment = f[9] == 'A' }
            end
        elseif kind == 'R' then
            RANGES[f[2]] = { min = tonumber(f[3]), max = tonumber(f[4]), integer = f[5] == '1' }
        elseif kind == 'A' then
            local targets = {}
            for name in f[4]:gmatch('[^,]+') do targets[#targets + 1] = name end
            ALIASES[f[2]] = { mode = f[3], targets = targets }
        elseif kind == 'O' then
            ITEMS[tonumber(f[2])].takeover = { base_projectile = tonumber(f[3]), src_projectile = tonumber(f[4]),
                new_projectile = tonumber(f[5]), src_damage = tonumber(f[6]), new_damage = tonumber(f[7]) }
        elseif kind == 'U' then
            local item = ITEMS[tonumber(f[2])]
            item.switches = item.switches or {}
            item.switches[#item.switches + 1] = { table = f[3], offset = tonumber(f[4]), projectile = tonumber(f[5]) }
        elseif kind == 'W' then
            ROWS[f[2] .. '|' .. f[3]] = f[4]
        elseif kind == 'X' then
            ITEMS[tonumber(f[2])].ammo_delta = { offset = tonumber(f[3]), expected = tonumber(f[4]) }
        elseif kind == 'N' then
            INDEXES[f[2] .. '|' .. f[3]] = { rva = tonumber(f[4], 16), slots = tonumber(f[5]) }
        elseif kind == 'G' then
            local item = ITEMS[tonumber(f[2])]
            item.magazine = { run_at = tonumber(f[3]), run_count = tonumber(f[4]), resource = f[5], base = {} }
            MAGAZINES[f[5]] = MAGAZINES[f[5]] or {}
            MAGAZINES[f[5]][#MAGAZINES[f[5]] + 1] = item
        elseif kind == 'H' then
            ITEMS[tonumber(f[2])].magazine.base[f[3]] = { table = f[4], record = f[5], offset = tonumber(f[6]),
                                                          storage = f[7], stock = tonumber(f[8]) }
        elseif kind == 'B' then
            local item = ITEMS[tonumber(f[2])]
            local blast = { kind = f[3], explosion = tonumber(f[4]), damage = tonumber(f[5]), own = f[6] == '1',
                            shared_damage = f[7] == '1', switches = {} }
            for switch in f[8]:gmatch('[^,]+') do
                local table_name, offset = switch:match('^(.-):(%d+)$')
                if table_name then
                    blast.switches[#blast.switches + 1] = { table = table_name, offset = tonumber(offset) }
                else
                    blast.switches[#blast.switches + 1] = { offset = tonumber(switch) }
                end
            end
            item.blasts = item.blasts or {}
            item.blasts[#item.blasts + 1] = blast
        elseif kind == 'S' then
            SPARE[f[2]] = {}
            for id in f[3]:gmatch('%d+') do SPARE[f[2]][#SPARE[f[2]] + 1] = tonumber(id) end
        elseif kind == 'P' then
            LIVE_WORDS[f[2]] = {}
            for offset in f[3]:gmatch('%d+') do LIVE_WORDS[f[2]][tonumber(offset)] = true end
        end
        count = count + 1
        if count % 16 == 0 then pause() end
    end
    collectgarbage('restart')
    log('data: ' .. #BUILDS .. ' builds, ' .. #SPEC_ORDER .. ' tables, ' .. (#ITEMS + 1) .. ' items, '
        .. field_count .. ' fields')
end

-- ---------------------------------------------------------------- build gate
local build = { state = 'unchecked', modules = {} }

local function hash_module(name)
    local info = { name = name or 'helldivers2.exe' }
    local base, path = A.module(name)
    if not base or not path then info.note = 'not loaded'; return info end
    info.path = path
    local handle, size = A.open(path)
    if not handle then info.note = 'file could not be opened'; return info end
    info.file_size = size
    local context = A.sha256_begin()
    if not context then
        info.note = 'SHA-256 unavailable'
    else
        local total, ok = 0, true
        while true do
            local n = A.read_file(handle)
            if n == nil then ok = false break end
            if n == 0 then break end
            if not A.sha256_update(context, n) then ok = false break end
            total = total + n
            pause()
        end
        local digest = A.sha256_finish(context)
        if ok and digest and total == size then info.sha256 = digest
        else info.note = 'hashing failed after ' .. total .. ' bytes' end
    end
    A.close(handle)
    return info
end

-- Sets build.state to 'verified' only when BOTH files hash to the same known build.
local function check_build()
    local exe, dll = hash_module(nil), hash_module('game.dll')
    build.modules = { exe, dll }
    build.state, build.label = 'unknown', nil
    for _, known in ipairs(BUILDS) do
        if exe.sha256 and dll.sha256 and exe.sha256 == known.exe and dll.sha256 == known.dll then
            build.state, build.label = 'verified', known.label
        end
    end
    log('build: ' .. build.state .. (build.label and (' (' .. build.label .. ')') or '')
        .. ' exe=' .. tostring(exe.sha256 or exe.note) .. ' dll=' .. tostring(dll.sha256 or dll.note))
end

-- ---------------------------------------------------------------- finding tables
local search = { passes = 0, allocations = 0, seconds = 0, slowest_query = 0, slowest_at = 0 }

local function valid_block(block)
    return A.u32(block.address) == LDLD and A.u32(block.address + 4) == 1
        and A.u32(block.address + 8) == block.type and A.u32(block.address + 12) == block.size
end

-- Follows a chain of back-to-back blocks from `address`; keeps the blocks of wanted tables.
local function walk(address, origin, found)
    local steps = 0
    while steps < 200000 do
        if A.u32(address) ~= LDLD or A.u32(address + 4) ~= 1 then return end
        local kind, size = A.u32(address + 8), A.u32(address + 12)
        if not kind or kind == 0 or not size or size == 0 or size > MAX_BLOCK then return end
        local spec = SPEC_BY_TYPE[kind]
        if spec and not found[address] then
            found[address] = { address = address, type = kind, size = size, spec = spec,
                               origin = steps == 0 and origin or 'chain' }
        end
        steps = steps + 1
        local after, next_address = address + 24 + size, nil
        for skip = 0, 16, 4 do
            if A.u32(after + skip) == LDLD and A.u32(after + skip + 4) == 1 then
                next_address = after + skip
                break
            end
        end
        if not next_address then return end
        address = next_address
        pause()
    end
end

-- One pass over the allocations of the process: is there a table at the start of each?
-- (In-game recon: every table we use sits there or in the chain behind one.)
local function find_tables()
    local started, found = A.now(), {}
    search.allocations = 0
    local cursor = ADDRESS_START
    while cursor < ADDRESS_END do
        local t0 = A.now()
        local base, size, allocated = A.allocation(cursor)
        local cost = A.now() - t0
        if cost > search.slowest_query then search.slowest_query, search.slowest_at = cost, cursor end
        if not base then break end
        if allocated then
            search.allocations = search.allocations + 1
            if A.readable_start(base, size) then
                if A.u32(base) == LDLD and A.u32(base + 4) == 1 then
                    walk(base, 'allocation+0', found)
                elseif A.u32(base + 4) == LDLD and A.u32(base + 8) == 1 then
                    walk(base + 4, 'allocation+4', found)
                end
            end
        end
        local next_cursor = base + size
        if next_cursor <= cursor then next_cursor = cursor + 4096 end
        cursor = next_cursor
        pause()
    end
    -- merge: keep parsed blocks that are still there, add new ones, drop the rest
    for _, name in ipairs(SPEC_ORDER) do
        local spec, kept = SPECS[name], {}
        for _, block in ipairs(spec.blocks) do
            if found[block.address] and found[block.address].size == block.size then
                kept[#kept + 1] = block
                found[block.address] = nil
            end
        end
        spec.blocks = kept
    end
    for _, block in pairs(found) do
        block.spec.blocks[#block.spec.blocks + 1] = block
    end
    for _, name in ipairs(SPEC_ORDER) do
        table.sort(SPECS[name].blocks, function(x, y) return x.address < y.address end)
    end
    search.passes = search.passes + 1
    search.seconds = A.now() - started
    state.passes = search.passes
end

-- Keyed table: buckets (u64 entity, u32 record index, u32 0), twice as many as entities, then
-- fixed-size records. The bucket count is derived from the content, never assumed.
local function parse_keyed(block)
    local payload, size, stride = block.address + 24, block.size, block.spec.stride
    local limit = math.floor(size / (16 + stride / 2)) + 4
    local count, live, top, fits = 0, 0, -1, {}
    local offset, stop = 0, false
    while not stop and offset + 16 <= size and count <= limit do
        local want = math.min(8192, size - offset)
        want = want - want % 16
        if want < 16 or not A.read(payload + offset, want) then break end
        local w = A.words
        for k = 0, want / 16 - 1 do
            local lo, hi, index, pad = w[k * 4], w[k * 4 + 1], w[k * 4 + 2], w[k * 4 + 3]
            if pad ~= 0 or index > 1000000 or count > limit then stop = true break end
            count = count + 1
            if lo ~= 0 or hi ~= 0 then
                live = live + 1
                if index > top then top = index end
            end
            local rest = size - count * 16
            if count == 2 * live and rest > 0 and rest % stride < 8 then
                local records = (rest - rest % stride) / stride
                if records > top and records <= live + 2 then
                    fits[#fits + 1] = { buckets = count, records = records }
                end
            end
        end
        offset = offset + want
        pause()
    end
    if #fits ~= 1 then return nil, #fits .. ' bucket layouts fit (need exactly 1)' end
    local fit, index = fits[1], {}
    offset = 0
    while offset < fit.buckets * 16 do
        local want = math.min(8192, fit.buckets * 16 - offset)
        if not A.read(payload + offset, want) then return nil, 'bucket array unreadable' end
        local w = A.words
        for k = 0, want / 16 - 1 do
            local lo, hi = w[k * 4], w[k * 4 + 1]
            if lo ~= 0 or hi ~= 0 then
                local key = string.format('%08X%08X', hi, lo)
                if index[key] == nil then
                    local record = w[k * 4 + 2]
                    if record >= fit.records then return nil, 'record index out of range' end
                    index[key] = record
                end
            end
        end
        offset = offset + want
        pause()
    end
    block.records_at, block.index, block.count = payload + fit.buckets * 16, index, fit.records
    block.limit = payload + size
    return true
end

-- Row table: DLArray (u64 absolute pointer in memory, u64 count), then rows carrying a u32 id.
local function parse_rows(block)
    local payload, size, stride = block.address + 24, block.size, block.spec.stride
    local pointer, count = A.u64(payload), A.u64(payload + 8)
    if not pointer or not count then return nil, 'array head unreadable' end
    local rows_at
    if pointer < size then rows_at = payload + pointer
    elseif pointer >= payload and pointer < payload + size then rows_at = pointer
    else return nil, 'rows are outside the block' end
    if count == 0 or (rows_at - payload) + count * stride > size then
        return nil, 'rows do not fit (count ' .. count .. ')'
    end
    local index = {}
    local per_read = math.max(1, math.floor(FILE_CHUNK / stride))
    local row = 0
    while row < count do
        local n = math.min(per_read, count - row)
        if not A.read(rows_at + row * stride, n * stride) then return nil, 'rows unreadable' end
        local bytes = A.buffer
        for k = 0, n - 1 do
            local at = k * stride + block.spec.id_at
            local id = bytes[at] + bytes[at + 1] * 256 + bytes[at + 2] * 65536 + bytes[at + 3] * 16777216
            if index[id] == nil then index[id] = row + k end
        end
        row = row + n
        pause()
    end
    block.records_at, block.index, block.count = rows_at, index, count
    block.limit = payload + size
    return true
end

-- Delta storage: five arrays; the fifth (pointer at +64, byte count at +72) is the raw data the
-- attachment deltas copy from.
local function parse_delta_storage(block)
    local payload = block.address + 24
    local pointer, count = A.u64(payload + 64), A.u64(payload + 72)
    if not pointer or not count or count == 0 or count > MAX_BLOCK then return nil, 'data array head unreadable' end
    if pointer < block.size then pointer = payload + pointer end
    block.records_at, block.index, block.count, block.limit = pointer, {}, count, pointer + count
    -- the third array (pointer at +32, count at +40): 12-byte runs, one per component an attachment changes
    local runs, run_count = A.u64(payload + 32), A.u64(payload + 40)
    if runs and run_count and run_count > 0 and run_count * 12 <= MAX_BLOCK then
        if runs < block.size then runs = payload + runs end
        block.components_at, block.components_end = runs, runs + run_count * 12
    end
    return true
end

local function parse_block(block)
    if block.index or block.problem then return block.index ~= nil end
    state.step = 'reading table ' .. block.spec.name
    local ok, why
    if block.spec.shape == 'K' then ok, why = parse_keyed(block)
    elseif block.spec.shape == 'S' then
        -- one record: the block is the record, and the arrays it points to follow it. Its id says which.
        local payload = block.address + 24
        local id = A.u32(payload + block.spec.id_at)
        if id == nil then
            ok, why = nil, 'the id is unreadable'
        else
            block.records_at, block.index, block.count, block.limit = payload, { [id] = 0 }, 1, payload + block.size
            ok = true
        end
    elseif block.spec.shape == 'D' then ok, why = parse_delta_storage(block)
    else ok, why = parse_rows(block) end
    if not ok then
        block.problem = why
        log(block.spec.name .. ' at ' .. hex(block.address) .. ' cannot be parsed: ' .. tostring(why))
    end
    return ok == true
end

-- Address of `field` in `block`, or nil when the record is not in this table.
local function field_address(block, field)
    if block.spec.shape == 'D' then
        if field.record == 'components' then
            if not block.components_at or block.components_at + field.offset + 4 > block.components_end then return nil end
            return block.components_at + field.offset
        end
        local address = block.records_at + field.offset
        if address + 4 > block.limit then return nil end
        return address
    end
    local key = field.record
    if block.spec.shape == 'R' or block.spec.shape == 'S' then key = tonumber(key) end
    local record = block.index[key]
    if record == nil then return nil end
    local address = block.records_at + record * block.spec.stride + field.offset
    if address < block.address + 24 or address + 4 > block.limit then return nil end
    return address
end

local function read_field(address, storage)
    local bits = A.u32(address)
    if bits == nil then return nil end
    if storage == 'f32' then return bits_to_f32(bits) end
    if storage == 'i32' and bits >= 2147483648 then return bits - 4294967296 end
    return bits
end

-- value -> bit pattern, or nil when it cannot be represented exactly as intended
local function encode(value, storage)
    if storage == 'f32' then
        local bits = A.f32_bits(value)
        if not close_enough(bits_to_f32(bits), value) then return nil end   -- encoder vs decoder
        return bits
    end
    if value ~= math.floor(value) then return nil end
    if storage == 'i32' then
        if value < -2147483648 or value > 2147483647 then return nil end
        if value < 0 then return value + 4294967296 end
        return value
    end
    if value < 0 or value > 4294967295 then return nil end
    return value
end

-- ---------------------------------------------------------------- rows of our own (experimental)
-- In-game probe (v0.3.2): the game finds a projectile or damage row as [index + id * 8], where
-- `index` is a fixed array inside game.dll, and it does not compare the id with the number of rows.
-- An id far above the real ones therefore reads its "slot" from memory above game.dll. We allocate
-- memory of our own there and put rows and pointers to those rows inside: the id that lands on such a
-- pointer is a new row id. Nothing of the game's is changed by this. A weapon is switched to such
-- ids only after each index has been checked against its table: every real id must lead to its row.
-- (In game, v0.4.1: a new projectile id works, solo and as a client in someone else's lobby.)
local OWN_TYPE = 0x4E574F4B      -- tag of our block; not a table type of the game
local OWN_CAPACITY = 256         -- rows of our own per table
local OWN_SIZE, OWN_SLOTS_AT, OWN_ROWS_AT = 0x20000, 0x100, 0x2000
local OWN_DAMAGE_AT = 60         -- the damage row id inside a projectile row
local OWN_TABLES = { 'ProjectileSettings', 'DamageSettings' }
local own = { state = 'unused', tables = {}, order = {} }

local function own_name(table_name) return 'own:' .. table_name end
local function known_index(table_name)
    return build.label and INDEXES[build.label .. '|' .. table_name] or nil
end

-- Allocates our block in reach of the game's indexes. -> true, or nil + reason
local function own_prepare()
    if own.block then return true end
    if own.state == 'failed' then return nil, own.note end
    if build.state ~= 'verified' then return nil, 'the game build is not verified' end
    local function fail(why)
        own.state, own.note = 'failed', why
        log('own rows: ' .. why)
        return nil, why
    end
    local dll = A.module('game.dll')
    if not dll then return fail('game.dll is not loaded') end
    -- where each table's slots and rows will sit inside the block
    local plan, rows_at, highest = {}, OWN_ROWS_AT, 0
    for n, name in ipairs(OWN_TABLES) do
        local known, spec = known_index(name), SPECS[name]
        if not known or not spec then return fail('this build has no known index for ' .. name) end
        local index = dll + known.rva
        if index % 8 ~= 0 or spec.stride % 4 ~= 0 then return fail('the ' .. name .. ' index is not aligned') end
        plan[n] = { name = name, index = index, stride = spec.stride, slots_at = OWN_SLOTS_AT + (n - 1) * OWN_CAPACITY * 8,
                    rows_at = rows_at }
        rows_at = rows_at + OWN_CAPACITY * spec.stride
        if index > highest then highest = index end
    end
    if OWN_SLOTS_AT + #OWN_TABLES * OWN_CAPACITY * 8 > OWN_ROWS_AT or rows_at > OWN_SIZE then
        return fail('the block layout does not fit')
    end
    local cursor, steps, attempts, address = highest, 0, 0, nil
    while cursor < ADDRESS_END and steps < 20000 and attempts < 16 do
        local base, size, allocated = A.allocation(cursor)
        if not base then break end
        local following = base + size
        if not allocated then
            local at = cursor + (-cursor) % 65536
            -- the id of our last slot must stay a positive 32-bit number, for every table
            local in_reach = true
            for _, t in ipairs(plan) do
                if (at + t.slots_at - t.index) / 8 + OWN_CAPACITY >= 2147483648 then in_reach = false end
            end
            if not in_reach then break end
            if at + OWN_SIZE <= following then
                attempts = attempts + 1
                if A.alloc(at, OWN_SIZE) == at then address = at break end
            end
        end
        if following <= cursor then following = cursor + 65536 end
        cursor = following
        steps = steps + 1
        pause()
    end
    if not address then return fail('no free memory in reach of the game\'s indexes') end
    local header = { LDLD, 1, OWN_TYPE, OWN_SIZE - 24 }
    for n, word in ipairs(header) do
        if not A.write_u32(address + (n - 1) * 4, word) or A.u32(address + (n - 1) * 4) ~= word then
            return fail('our own memory at ' .. hex(address) .. ' cannot be written')
        end
    end
    own.block = address
    for _, t in ipairs(plan) do
        local own_spec = { name = own_name(t.name), type = OWN_TYPE, shape = 'R', stride = t.stride, id_at = 0, blocks = {} }
        t.block = { address = address, type = OWN_TYPE, size = OWN_SIZE - 24, spec = own_spec, origin = 'own',
                    records_at = address + t.rows_at, index = {}, count = 0, limit = address + OWN_SIZE }
        own_spec.blocks[1] = t.block
        SPECS[own_spec.name] = own_spec
        t.first_id, t.count, t.users = (address + t.slots_at - t.index) / 8, 0, {}
        own.tables[t.name] = t
        log(string.format('own rows: %s index at %s, first new id %.0f', t.name, hex(t.index), t.first_id))
    end
    own.state = 'ready'
    log('own rows: block at ' .. hex(address))
    return true
end

-- The new row id of `item` in `table_name`: a copy of row `source`. A projectile row also gets
-- `damage` as its damage row id. -> id, or nil + reason
local function own_row(item, table_name, source, damage, purpose)
    local ok, why = own_prepare()
    if not ok then return nil, why end
    local t = own.tables[table_name]
    local key = item.name .. (purpose or '')
    local user = t.users[key]
    if user then return user.id end
    if t.count >= OWN_CAPACITY then return nil, 'no room for another row of our own' end
    local stock = ROWS[table_name .. '|' .. source]
    if not stock or #stock ~= t.stride * 2 then return nil, 'the stock row ' .. table_name .. ' ' .. source .. ' is not known' end
    local k = t.count
    local id, row_at, slot_at = t.first_id + k, t.block.records_at + k * t.stride, own.block + t.slots_at + k * 8
    for offset = 0, t.stride - 4, 4 do
        local word = hex_word(stock, offset)
        if offset == 0 then word = id elseif damage and offset == OWN_DAMAGE_AT then word = damage end
        if not A.write_u32(row_at + offset, word) or A.u32(row_at + offset) ~= word then
            return nil, 'our own row could not be written'
        end
        if offset % 64 == 60 then pause() end
    end
    local high = math.floor(row_at / 4294967296)
    if not A.write_u32(slot_at, row_at - high * 4294967296) or not A.write_u32(slot_at + 4, high)
        or A.u64(slot_at) ~= row_at or t.index + id * 8 ~= slot_at then
        return nil, 'the slot of our own row could not be written'
    end
    t.block.index[id], t.count, t.block.count = k, k + 1, k + 1
    t.users[key] = { id = id, row = row_at, slot = slot_at, source = source, name = key, table = table_name }
    own.order[#own.order + 1] = t.users[key]
    log(string.format('own rows: %s -> new %s id %.0f (row at %s, copy of row %d)', key, table_name, id,
                      hex(row_at), source))
    return id
end

-- Does the game's index lead every real id of `table_name` to its row in a table we found?
-- -> true; false + reason (it does not: never switch a weapon); nil + reason (cannot tell yet)
local function own_index_ok(table_name)
    local known, spec, t = known_index(table_name), SPECS[table_name], own.tables[table_name]
    if not t or not known then return false, 'no block of our own' end
    local bytes = known.slots * 8
    if not A.readable_private(t.index) or not A.readable_private(t.index + bytes - 1) then
        return nil, 'the ' .. table_name .. ' index is not in memory yet'
    end
    local parsed, reason = 0, 'the ' .. table_name .. ' table is not loaded yet'
    for _, block in ipairs(spec.blocks) do
        if parse_block(block) then
            parsed = parsed + 1
            if block.count + 1 ~= known.slots then
                reason = table_name .. ' has ' .. block.count .. ' rows, the index was measured with ' .. (known.slots - 1)
            elseif not A.read(t.index, bytes) then
                reason = 'the ' .. table_name .. ' index cannot be read'
            else
                local good = A.words[0] == 0 and A.words[1] == 0
                for id, row in pairs(block.index) do
                    local address = block.records_at + row * spec.stride
                    local high = math.floor(address / 4294967296)
                    if id < 1 or id >= known.slots or A.words[2 * id + 1] ~= high
                        or A.words[2 * id] ~= address - high * 4294967296 then
                        good = false
                        break
                    end
                end
                if good then return true end
                reason = 'the ' .. table_name .. ' index does not lead to the rows of the table'
            end
        end
        pause()
    end
    if parsed == 0 then return nil, reason end
    return false, reason
end

-- ---------------------------------------------------------------- borrowed rows
-- Explosion ids are compared with the number of rows (probe v0.3.2), so an explosion row of an item's
-- own cannot have a new id: an existing row is borrowed from a short list of rows that no table in
-- memory refers to (census v0.8.0). Such a row is overwritten with a copy of the item's row and put
-- back when it is no longer needed. An id that only code uses is invisible to the census, so the list
-- is a guess; the canary (see build_desired) is the in-game test of it.
local spare = { users = {}, order = {}, next = {} }

-- The borrowed row of `key` in `table_name`. -> row id, or nil + reason
local function spare_row(key, table_name, source)
    local user = spare.users[table_name .. '|' .. key]
    if user then return user.id end
    local pool = SPARE[table_name] or {}
    local n = (spare.next[table_name] or 0) + 1
    if n > #pool then return nil, 'no row is left to borrow in ' .. table_name end
    spare.next[table_name] = n
    user = { id = pool[n], name = key, table = table_name, source = source }
    spare.users[table_name .. '|' .. key], spare.order[#spare.order + 1] = user, user
    log(string.format('borrowed rows: %s -> %s row %d (as a copy of row %d)', key, table_name, user.id, source))
    return user.id
end

-- ---------------------------------------------------------------- config
local config = { text = nil, enabled = true, reload_vk = 0x79, reload_key = 'F10', auto_reload = 0,
                 menu_vk = 0x78, menu_key = 'F9',
                 own_rows = true,
                 rescan = DEFAULT_RESCAN_SECONDS, requests = {}, problems = {} }
local overrides = {}     -- 'category:item:stat' -> expression, set through the menu or the API
local preset_name = nil  -- the menu's active preset: the file `overrides` is kept in
-- field key -> { field, value, copies = { [block address] = { address, original, block } },
--                state, note }: what the engine has touched in memory
local applied = {}
local desired = {}       -- field key -> { field, value, sources = { request, ... } }

local TEMPLATE = table.concat({
    '# BYOG config. Lines starting with # are comments.',
    '# After editing, press the reload key in game (default F10). Remove a line to get the',
    "# game's own value back. Items, stats and allowed ranges: see catalog.txt in this folder.",
    '',
    '[settings]',
    'enabled = true',
    'reload_key = F10',
    'auto_reload_seconds = 0',
    '',
    '# Example (remove the # to use it):',
    '# [weapon: assault_rifle]',
    '# damage = 120',
    '# rpm = 150%',
    '# recoil = -5',
    '',
}, '\r\n')

local function parse_bool(text)
    text = text:lower()
    if text == 'true' or text == 'yes' or text == 'on' or text == '1' then return true end
    if text == 'false' or text == 'no' or text == 'off' or text == '0' then return false end
    return nil
end

-- 'N', 'N%', '+N', '-N' applied to the game's value -> number, or nil + reason
local function evaluate(expression, stock)
    local text = expression:gsub('%s+', ''):gsub(',', '.')
    local percent = text:match('^([%d%.]+)%%$')
    if percent then
        local n = tonumber(percent)
        if not n then return nil, 'not a number' end
        return stock * n / 100
    end
    local sign, amount = text:match('^([%+%-])([%d%.]+)$')
    if sign then
        local n = tonumber(amount)
        if not n then return nil, 'not a number' end
        if sign == '+' then return stock + n end
        return stock - n
    end
    local n = text:match('^[%d%.]+$') and tonumber(text)
    if not n then return nil, 'not a number (use 120, 150%, +15 or -5)' end
    return n
end

-- Turns one request (category, item, stat, expression) into field targets, or rejects it.
local function get_field(table_name, record, offset, storage, stock)
    local key = field_key(table_name, record, offset)
    local field = FIELDS[key]
    if not field then
        field = { key = key, table = table_name, record = record, offset = offset, storage = storage,
                  stock = stock, users = {} }
        FIELDS[key] = field
    end
    return field
end

-- With "own bullet", a stat of the shared projectile / damage row is set on the weapon's own row instead.
-- -> the field to write, and whether it was redirected
local function own_row_field(item, field)
    local t = item.active_takeover or item.takeover
    local source, new_row = nil, nil
    if field.table == 'ProjectileSettings' and field.record == tostring(t.src_projectile) then
        source, new_row = t.src_projectile, t.new_projectile
    elseif field.table == 'DamageSettings' and field.record == tostring(t.src_damage) then
        source, new_row = t.src_damage, t.new_damage
    end
    if not new_row then return field, false end
    local own_field
    if t.fresh then
        -- a row of our own starts as a copy of the weapon's row
        own_field = get_field(own_name(field.table), string.format('%.0f', new_row), field.offset, 'u32',
                              hex_word(ROWS[field.table .. '|' .. source], field.offset))
    else
        own_field = get_field(field.table, tostring(new_row), field.offset, 'u32',
                              hex_word(ROWS[field.table .. '|' .. new_row], field.offset))
    end
    own_field.exact = true
    return own_field, true
end

-- With an explosion of its own, a stat of the shared explosion row or of its damage row is set on the
-- item's own rows instead. -> the field to write and its group, or nil
local function own_blast_field(item, field)
    for _, a in ipairs(item.active_blasts or {}) do
        local own_field = nil
        if a.new_explosion and field.table == 'ExplosionSettings' and field.record == tostring(a.blast.explosion) then
            own_field = get_field('ExplosionSettings', tostring(a.new_explosion), field.offset, 'u32',
                                  hex_word(ROWS['ExplosionSettings|' .. a.new_explosion], field.offset))
        elseif a.own_damage and field.table == 'DamageSettings' and field.record == tostring(a.blast.damage) then
            own_field = get_field(own_name('DamageSettings'), string.format('%.0f', a.new_damage), field.offset, 'u32',
                                  hex_word(ROWS['DamageSettings|' .. a.blast.damage], field.offset))
        end
        if own_field then
            own_field.exact = true
            return own_field, a.group
        end
    end
    return nil
end

-- `blast_from = <item>`: this item explodes like that one. The value is not a number but the name of
-- another item (ids change between builds, names do not): its explosion row id is written into the
-- weapon's own projectile row, or into a throwable's own component record. The explosion itself stays
-- the source item's: changing the source's blast changes both.
local BLAST_ON_IMPACT = 144      -- ProjectileInfo.explosion_type_on_impact
local function resolve_blast_from(request, item, own_bullet)
    local source, wanted = nil, trim(request.expression):lower()
    for _, category in ipairs({ 'weapon', 'throwable', 'stratagem_weapon', 'enemy_weapon', 'unknown_weapon' }) do
        source = source or ITEM_BY_NAME[category .. ':' .. wanted]
    end
    if not source or not source.blasts then
        request.status, request.reason = 'rejected', 'blast_from takes the name of an item that explodes (see catalog.txt)'
        return
    end
    local explosion = source.blasts[1].explosion
    request.targets = {}
    local function target(field, stock)
        field.exact = true
        request.targets[#request.targets + 1] = { stat = 'blast_from', field = field, value = explosion,
            text = source.name .. ' (explosion row ' .. explosion .. ')', was_text = 'explosion row ' .. stock, own = true }
    end
    if item.takeover then
        local t = own_bullet[item] and own_bullet[item].takeover
        if not (t and t.fresh) then
            request.status, request.reason = 'rejected', 'blast_from needs the weapon\'s own projectile row (own_rows = auto)'
            return
        end
        local stock = hex_word(ROWS['ProjectileSettings|' .. t.src_projectile], BLAST_ON_IMPACT)
        target(get_field(own_name('ProjectileSettings'), string.format('%.0f', t.new_projectile), BLAST_ON_IMPACT, 'u32',
                         stock), stock)
    elseif item.blasts and item.blasts[1].kind == 'C' then
        for _, s in ipairs(item.blasts[1].switches) do
            target(get_field(s.table, item.entity, s.offset, 'u32', item.blasts[1].explosion), item.blasts[1].explosion)
            request.targets[#request.targets].own = nil      -- the item's own record: a plain value
        end
    else
        request.status, request.reason = 'rejected', 'blast_from is not possible for this item'
        return
    end
    request.status = 'accepted'
end

local function resolve_request(request, own_bullet)
    local item = ITEM_BY_NAME[request.category .. ':' .. request.item:lower()]
    if not item then
        request.status, request.reason = 'rejected', 'unknown ' .. request.category .. ' (see catalog.txt)'
        return
    end
    local stats, nonzero = { request.stat }, false
    local alias = ALIASES[request.stat]
    if alias then stats, nonzero = alias.targets, alias.mode == 'nonzero' end
    if request.stat == 'blast_from' then return resolve_blast_from(request, item, own_bullet) end
    request.targets = {}
    for _, stat in ipairs(stats) do
        local entry, range = item.stats[stat], RANGES[stat]
        if entry and range and not (nonzero and entry.field.stock == 0) then
            local value, why = evaluate(request.expression, entry.field.stock)
            if not value then request.status, request.reason = 'rejected', why return end
            if range.integer or entry.field.storage ~= 'f32' then value = math.floor(value + 0.5) end
            if value ~= value or value < range.min or value > range.max then
                request.status = 'rejected'
                request.reason = string.format('%s = %s is outside the allowed range %s .. %s', stat,
                    show(value, 'f32'), show(range.min, 'f32'), show(range.max, 'f32'))
                return
            end
            local bits = encode(value, entry.field.storage)
            if bits == nil then
                request.status, request.reason = 'rejected', stat .. ' = ' .. tostring(value) .. ' cannot be stored'
                return
            end
            local target = { stat = stat, field = entry.field, value = value,
                             text = show(value, entry.field.storage), attachment = entry.attachment }
            local base = entry.attachment and config.own_rows and item.magazine and item.magazine.base[stat]
            if base then
                -- the value goes into the weapon's own record; the attachment's is switched off (build_desired)
                target.field = get_field(base.table, base.record, base.offset, base.storage, base.stock)
                if #target.field.users == 0 then target.field.users[1] = item.name .. '.' .. stat end
                target.was_text, target.magazine, target.attachment = show(entry.field.stock, entry.field.storage), item, nil
            end
            if own_bullet[item] then
                local field, redirected = own_row_field(item, entry.field)
                if redirected then
                    -- the own row is written as raw words; keep the readable numbers for the report
                    target.field, target.value = field, bits
                    target.was_text, target.own = show(entry.field.stock, entry.field.storage), true
                end
            end
            if not target.own then
                local field, group = own_blast_field(item, entry.field)
                if field then
                    -- the own rows are written as raw words; keep the readable numbers for the report
                    target.field, target.value, target.group = field, bits, group
                    target.was_text, target.own = show(entry.field.stock, entry.field.storage), true
                end
            end
            request.targets[#request.targets + 1] = target
            -- a value the game keeps in several places: every one of them gets it
            for _, extra in ipairs(entry.more or {}) do
                request.targets[#request.targets + 1] = { stat = stat, field = extra, value = value,
                                                          text = show(value, extra.storage) }
            end
        elseif not alias then
            request.status = 'rejected'
            request.reason = 'this ' .. request.category .. ' has no stat "' .. stat .. '" (see catalog.txt)'
            return
        end
    end
    if #request.targets == 0 then
        request.status, request.reason = 'rejected', 'nothing to set: no "' .. request.stat .. '" value on this item'
        return
    end
    request.status = 'accepted'
end

-- Is `stat` of `item` a value of blast `b`: in its explosion row, in the explosion's damage row?
local function blast_touch(item, b, stat)
    local stats, in_row, in_damage = { stat }, false, false
    if ALIASES[stat] then stats = ALIASES[stat].targets end
    for _, name in ipairs(stats) do
        local field = item.stats[name] and item.stats[name].field
        if field and field.table == 'ExplosionSettings' and field.record == tostring(b.explosion) then in_row = true end
        if field and b.damage ~= 0 and field.table == 'DamageSettings' and field.record == tostring(b.damage) then
            in_damage = true
        end
    end
    return in_row, in_damage
end

-- Does `stat` of `item` live in the projectile / damage row the weapon shares with others?
local function touches_shared_rows(item, stat)
    if stat == 'blast_from' then return true end        -- written into the weapon's own projectile row
    local t, stats = item.takeover, { stat }
    if ALIASES[stat] then stats = ALIASES[stat].targets end
    for _, name in ipairs(stats) do
        local field = item.stats[name] and item.stats[name].field
        if field and ((field.table == 'ProjectileSettings' and field.record == tostring(t.src_projectile))
            or (field.table == 'DamageSettings' and field.record == tostring(t.src_damage))) then
            return true
        end
    end
    for _, b in ipairs(item.blasts or {}) do
        if b.kind == 'P' and not b.own then
            -- an explosion row of its own is reached through a projectile row of its own
            local in_row, in_damage = blast_touch(item, b, stat)
            if in_row or in_damage then return true end
        end
    end
    return false
end

-- Parses the config text and the API overrides into `desired`.
local function build_desired(text)
    config.requests, config.problems = {}, {}
    config.enabled, config.reload_key, config.reload_vk = true, 'F10', 0x79
    config.menu_key, config.menu_vk = 'F9', 0x78
    -- the research file is only written when config.txt asks for it (`[settings] research = true`)
    config.research = false
    -- the headings of the menu's value list start closed; `[settings] menu_sections = open` starts them open
    config.sections_open = false
    config.auto_reload, config.rescan, config.own_rows = 0, DEFAULT_RESCAN_SECONDS, true
    local section, line_number = nil, 0
    local by_stat = {}   -- 'category:item:stat' -> request (a later line replaces an earlier one)
    for raw in ((text or '') .. '\n'):gmatch('([^\n]*)\n') do
        line_number = line_number + 1
        local line = trim((raw:gsub('#.*$', ''):gsub('\r', '')))
        if line ~= '' then
            local header = line:match('^%[(.-)%]$')
            local key, value = line:match('^([^=]+)=(.*)$')
            if header then
                local category, item = header:match('^%s*([%w_]+)%s*:%s*(.-)%s*$')
                if trim(header):lower() == 'settings' then
                    section = { settings = true }
                elseif category and item ~= '' then
                    section = { category = category:lower(), item = item }
                else
                    section = nil
                    config.problems[#config.problems + 1] = 'line ' .. line_number .. ': cannot read section "' .. line .. '"'
                end
            elseif key and section then
                key, value = trim(key):lower(), trim(value)
                if section.settings then
                    if key == 'enabled' and parse_bool(value) ~= nil then
                        config.enabled = parse_bool(value)
                    elseif key == 'reload_key' and value:upper():match('^F%d%d?$')
                        and tonumber(value:sub(2)) >= 1 and tonumber(value:sub(2)) <= 12 then
                        config.reload_key = value:upper()
                        config.reload_vk = 0x6F + tonumber(value:sub(2))
                    elseif key == 'menu_key' and value:upper():match('^F%d%d?$')
                        and tonumber(value:sub(2)) >= 1 and tonumber(value:sub(2)) <= 12 then
                        config.menu_key = value:upper()
                        config.menu_vk = 0x6F + tonumber(value:sub(2))
                    elseif key == 'auto_reload_seconds' and tonumber(value) and tonumber(value) >= 0 then
                        config.auto_reload = tonumber(value)
                    elseif key == 'rescan_seconds' and tonumber(value) and tonumber(value) >= 0 then
                        config.rescan = tonumber(value)
                    elseif key == 'probe' or key == 'census' or key == 'canary' or key == 'dump_globals'
                        or key == 'ui_probe' then
                        -- research settings of the test builds: gone. Accepted, so that an old config is no problem.
                    elseif key == 'research' and parse_bool(value) ~= nil then
                        config.research = parse_bool(value)
                    elseif key == 'menu_sections' and (value:lower() == 'open' or value:lower() == 'closed') then
                        config.sections_open = value:lower() == 'open'
                    elseif key == 'own_rows' and (value:lower() == 'auto' or parse_bool(value) ~= nil) then
                        config.own_rows = value:lower() == 'auto' or parse_bool(value) == true
                    else
                        config.problems[#config.problems + 1] = 'line ' .. line_number .. ': unknown setting "' .. line .. '"'
                    end
                else
                    local request = { line = line_number, category = section.category, item = section.item,
                                      stat = key, expression = value, text = line }
                    by_stat[section.category .. ':' .. section.item:lower() .. ':' .. key] = request
                    config.requests[#config.requests + 1] = request
                end
            else
                config.problems[#config.problems + 1] = 'line ' .. line_number .. ': cannot read "' .. line .. '"'
            end
        end
    end
    for key, expression in pairs(overrides) do
        local category, item, stat = key:match('^([^:]+):([^:]+):(.+)$')
        local previous = by_stat[key]
        if previous then previous.status, previous.reason = 'replaced', 'replaced through the API' end
        local request = { line = 0, category = category, item = item, stat = stat, expression = expression,
                          text = stat .. ' = ' .. expression .. ' (API)' }
        by_stat[key] = request
        config.requests[#config.requests + 1] = request
    end
    -- a later line for the same item and stat replaces the earlier one
    for _, request in ipairs(config.requests) do
        local key = request.category .. ':' .. request.item:lower() .. ':' .. request.stat
        if not request.status and by_stat[key] ~= request then
            request.status, request.reason = 'replaced', 'a later line sets the same stat'
        end
    end
    desired = {}
    if not config.enabled then
        for _, request in ipairs(config.requests) do
            if not request.status then request.status, request.reason = 'off', 'enabled = false' end
        end
        return
    end
    -- "own_bullet = true" first: it decides where the other lines of that weapon go
    local own_bullet, declined = {}, {}
    -- brand-new damage and projectile ids in memory of our own; a failure is written into `request`
    local function fresh_rows(item, request)
        local t = item.takeover
        local damage_id, why = own_row(item, 'DamageSettings', t.src_damage)
        local id = nil
        if damage_id then id, why = own_row(item, 'ProjectileSettings', t.src_projectile, damage_id) end
        if not id then
            request.status, request.reason = 'rejected', 'new row ids are not possible: ' .. tostring(why)
            return nil
        end
        -- other rounds of the same weapon (tracers in a belt): a row of their own each, on the same damage row
        local rounds = {}
        for _, s in ipairs(item.switches or {}) do
            local stock = ROWS['ProjectileSettings|' .. s.projectile]
            if s.projectile ~= t.src_projectile and rounds[s.projectile] == nil and stock
                and hex_word(stock, OWN_DAMAGE_AT) == t.src_damage then
                rounds[s.projectile] = own_row(item, 'ProjectileSettings', s.projectile, damage_id, ':round' .. s.projectile)
                    or false
            end
        end
        return { base_projectile = t.base_projectile, src_projectile = t.src_projectile, new_projectile = id,
                 src_damage = t.src_damage, new_damage = damage_id, fresh = true, rounds = rounds }
    end
    for _, request in ipairs(config.requests) do
        if not request.status and request.stat == 'own_bullet' then
            local item = ITEM_BY_NAME[request.category .. ':' .. request.item:lower()]
            local fresh = trim(request.expression):lower() == 'new'
            local wanted = fresh or parse_bool(request.expression)
            if not item then
                request.status, request.reason = 'rejected', 'unknown ' .. request.category .. ' (see catalog.txt)'
            elseif wanted == nil then
                request.status, request.reason = 'rejected', 'own_bullet takes true, false or new'
            elseif not item.takeover then
                request.status, request.reason = 'rejected', 'own_bullet is not available for this weapon yet'
            elseif not wanted then
                request.status, request.reason = 'off', 'own_bullet = false'
            else
                local t = item.takeover
                if fresh then
                    t = fresh_rows(item, request)
                elseif t.new_projectile == 0 then
                    request.status = 'rejected'
                    request.reason = 'own_bullet = true needs a spare row, and none is assigned to this weapon; use own_bullet = new'
                end
                if not request.status then
                    request.status, request.targets, request.own_item, request.takeover = 'accepted', {}, item, t
                    item.active_takeover = t
                    own_bullet[item] = request
                end
            end
            -- an own_bullet line that did not take effect (false, or refused) is the user's word:
            -- such a weapon is not given rows automatically
            if item and request.status ~= 'accepted' then declined[item] = true end
        end
    end
    -- Automatic: a weapon whose shared projectile / damage values are changed gets rows of its own,
    -- so that the change reaches this weapon only.
    if config.own_rows then
        local automatic = {}
        for _, request in ipairs(config.requests) do
            local item = not request.status and ITEM_BY_NAME[request.category .. ':' .. request.item:lower()]
            if item and item.takeover and not own_bullet[item] and not declined[item]
                and touches_shared_rows(item, request.stat) then
                local auto = { line = request.line, category = request.category, item = request.item, stat = 'own_bullet',
                               expression = 'new', text = 'rows of its own (automatic)', automatic = true }
                local t = fresh_rows(item, auto)
                if t then
                    auto.status, auto.targets, auto.own_item, auto.takeover = 'accepted', {}, item, t
                    item.active_takeover = t
                    own_bullet[item] = auto
                else
                    declined[item] = true      -- said once; this weapon's values then go to the shared rows
                end
                automatic[#automatic + 1] = auto
            end
        end
        for _, auto in ipairs(automatic) do config.requests[#config.requests + 1] = auto end
    end
    -- Explosions of their own (automatic). A blast stat of an item whose explosion row is reached by
    -- something else gets a borrowed explosion row; a blast damage stat whose damage row is shared gets
    -- a new damage id. A weapon needs its own projectile row for the first (the pass above gives it).
    local blasts = {}
    for _, item in pairs(ITEMS) do item.active_blasts = nil end
    if config.own_rows then
        local notes, refused = {}, {}
        for _, request in ipairs(config.requests) do
            local item = not request.status and request.stat ~= 'own_bullet' and request.stat ~= 'blast_from'
                and ITEM_BY_NAME[request.category .. ':' .. request.item:lower()]
            for _, b in ipairs(item and not declined[item] and item.blasts or {}) do
                local in_row, in_damage = blast_touch(item, b, request.stat)
                local t = own_bullet[item] and own_bullet[item].takeover
                local same_damage = t and b.damage == t.src_damage     -- the round and its blast use one damage row
                local a = nil
                for _, active in ipairs(item.active_blasts or {}) do
                    if active.blast == b then a = active end
                end
                if (in_row or in_damage) and not a and not refused[b] then
                    local why = nil
                    if not b.own then
                        if b.kind == 'P' and not (t and t.fresh) then
                            why = 'the weapon has no projectile row of its own'
                        else
                            local id
                            id, why = spare_row(item.name .. ':' .. b.explosion, 'ExplosionSettings', b.explosion)
                            if id then a = { new_explosion = id } end
                        end
                    elseif in_damage and (b.shared_damage or same_damage) then
                        a = {}
                    end
                    local note = { line = request.line, category = request.category, item = request.item, stat = 'own_blast',
                                   expression = 'new', text = 'explosion of its own (automatic)', automatic = true }
                    if a then
                        a.blast, a.item, a.takeover, a.request = b, item, t, note
                        a.group = 'blast:' .. item.name .. ':' .. b.explosion
                        item.active_blasts = item.active_blasts or {}
                        item.active_blasts[#item.active_blasts + 1] = a
                        blasts[#blasts + 1] = a
                        note.status, note.targets, note.blast = 'accepted', {}, a
                        notes[#notes + 1] = note
                    elseif why then
                        refused[b] = true
                        note.status, note.reason = 'rejected', why .. '; its blast values go to the shared rows'
                        notes[#notes + 1] = note
                    end
                end
                -- the damage row: of its own when the explosion row is borrowed, or when a damage value is set
                if a and b.damage ~= 0 and not a.new_damage and (a.new_explosion or in_damage) then
                    if same_damage then
                        a.new_damage = t.new_damage
                    else
                        local id, why = own_row(item, 'DamageSettings', b.damage, nil, ':blast' .. b.explosion)
                        if id then a.new_damage, a.own_damage = id, true else a.problem = why end
                    end
                end
            end
        end
        for _, note in ipairs(notes) do config.requests[#config.requests + 1] = note end
    end
    for _, request in ipairs(config.requests) do
        if not request.status then resolve_request(request, own_bullet) end
    end
    -- A line that names one value wins over a shortcut that also covers it: with all_health = 300% and
    -- part_leg_left_health = 10 the leg gets 10. (In game, v0.12.0, the two lines rejected each other.)
    local direct = {}
    for _, request in ipairs(config.requests) do
        if request.status == 'accepted' and not ALIASES[request.stat] then
            for _, target in ipairs(request.targets) do
                direct[request.category .. ':' .. request.item:lower() .. ':' .. target.stat] = request.line
            end
        end
    end
    for _, request in ipairs(config.requests) do
        if request.status == 'accepted' and ALIASES[request.stat] then
            local kept = {}
            for _, target in ipairs(request.targets) do
                local line = direct[request.category .. ':' .. request.item:lower() .. ':' .. target.stat]
                if line then
                    request.yielded = (request.yielded and (request.yielded .. ', ') or '') .. target.stat
                        .. ' (line ' .. line .. ')'
                else
                    kept[#kept + 1] = target
                end
            end
            request.targets = kept
        end
    end
    -- shared values: different targets for the same field reject every request involved
    local claims = {}
    for _, request in ipairs(config.requests) do
        if request.status == 'accepted' then
            for _, target in ipairs(request.targets) do
                local claim = claims[target.field.key]
                if not claim then
                    claims[target.field.key] = { value = target.value, requests = { request }, field = target.field }
                else
                    claim.requests[#claim.requests + 1] = request
                    if not same_value(target.field.storage, claim.value, target.value) then claim.conflict = true end
                end
            end
        end
    end
    for _, claim in pairs(claims) do
        if claim.conflict then
            local lines = {}
            for _, request in ipairs(claim.requests) do lines[#lines + 1] = request.line end
            table.sort(lines)
            for _, request in ipairs(claim.requests) do
                request.status = 'rejected'
                request.reason = 'lines ' .. table.concat(lines, ', ')
                    .. ' ask for different values of the same shared value (' .. claim.field.table .. ' '
                    .. claim.field.record .. ' +' .. claim.field.offset .. ')'
            end
        end
    end
    for _, request in ipairs(config.requests) do
        if request.status == 'accepted' then
            for _, target in ipairs(request.targets) do
                local entry = desired[target.field.key]
                if not entry then
                    entry = { field = target.field, value = target.value, sources = {} }
                    desired[target.field.key] = entry
                end
                entry.sources[#entry.sources + 1] = request
                if target.own then entry.group, entry.order = target.group or request.item:lower(), 1 end
            end
        end
    end
    -- A value the game will cap: more magazines at the start than the weapon may carry (seen in game,
    -- v0.8.0: mags_start = 10 with mags_max left at 8 started with 8). Said on the line, never "fixed":
    -- one line changes one value.
    local wanted = {}
    for _, request in ipairs(config.requests) do
        if request.status == 'accepted' then
            for _, target in ipairs(request.targets) do
                wanted[request.category .. ':' .. request.item:lower() .. ':' .. target.stat] = { request = request, target = target }
            end
        end
    end
    for key, w in pairs(wanted) do
        if w.target.stat == 'mags_start' then
            local item = ITEM_BY_NAME[w.request.category .. ':' .. w.request.item:lower()]
            local max = wanted[(key:gsub('mags_start$', 'mags_max'))]
            local limit = max and tonumber(max.target.text) or (item.stats.mags_max and item.stats.mags_max.field.stock)
            local start = tonumber(w.target.text)
            if limit and start and start > limit then
                w.request.warning = string.format('mags_start %d is above mags_max %d: the game starts with %d. '
                    .. 'Set mags_max as well', start, limit, limit)
            end
        end
    end
    -- More ammunition than a resupply can fill. Seen in game (v1.0.0, minigun): with 1500 rounds the weapon
    -- starts a mission with 1500, but a resupply only fills up to 1023 (the largest 10-bit number), so the
    -- limit is in the game's resupply, not in the value. Said on the line, the value is written as asked.
    local RESUPPLY_LIMIT = 1023
    for _, w in pairs(wanted) do
        local amount = tonumber(w.target.text)
        if (w.target.stat == 'charges' or w.target.stat == 'rounds_max') and amount and amount > RESUPPLY_LIMIT then
            w.request.warning = string.format('%s %d is above %d: the game starts with %d, but a resupply fills up to '
                .. '%d at most', w.target.stat, amount, RESUPPLY_LIMIT, amount, RESUPPLY_LIMIT)
        end
    end
    -- A vehicle part that outlasts the vehicle: damage to a part also goes to the main health (to_main),
    -- so a part whose health is above what the main health can pay for never breaks (seen in game,
    -- v0.11.0: a leg with 100000 health, the exosuit was destroyed first). Said on the line, not "fixed".
    local function effective(item_key, item, stat)
        local w = wanted[item_key .. ':' .. stat]
        if w then return tonumber(w.target.text) end
        return item.stats[stat] and item.stats[stat].field.stock
    end
    local function outlasts(item_key, item, part)
        local main, share = effective(item_key, item, 'health'), effective(item_key, item, 'part_' .. part .. '_to_main')
        local health = effective(item_key, item, 'part_' .. part .. '_health')
        if main and share and health and share > 0 and health * share > main then return health, main, share end
        return nil
    end
    for _, w in pairs(wanted) do
        local item_key = w.request.category .. ':' .. w.request.item:lower()
        local item = ITEM_BY_NAME[item_key]
        local part = w.target.stat:match('^part_(.+)_health$') or w.target.stat:match('^part_(.+)_to_main$')
        local parts = part and { part } or {}
        if w.target.stat == 'health' and w.request.category == 'vehicle' then
            for _, stat in ipairs(item.stat_order) do
                parts[#parts + 1] = stat:match('^part_(.+)_health$')
            end
        end
        for _, name in ipairs(parts) do
            local health, main, share = outlasts(item_key, item, name)
            if health and not w.request.warning then
                w.request.warning = string.format('part %s has %d health and passes %d%% of its damage on, the main health '
                    .. 'is %d: the vehicle is destroyed before this part breaks. Raise health, lower part_%s_to_main, or '
                    .. 'use all_health to scale everything together', name, health, share * 100, main, name)
            end
        end
    end
    -- Magazine values of a weapon's own. Where a default magazine attachment sets the magazine values,
    -- the attachment is shared by every weapon that carries it. Its run of magazine deltas is switched
    -- off (count 0 in the delta storage), and every weapon that carries this magazine by default gets
    -- the values in its own record: the config's for the weapon being changed, the attachment's stock
    -- values for the others. order 1 = the records, order 2 = the switch, as with own bullets.
    local magazines = {}
    for _, request in ipairs(config.requests) do
        if request.status == 'accepted' then
            for _, target in ipairs(request.targets) do
                if target.magazine then magazines[target.magazine.magazine.resource] = target.magazine.magazine end
            end
        end
    end
    for resource, magazine in pairs(magazines) do
        local group = 'magazine:' .. resource
        for _, item in ipairs(MAGAZINES[resource]) do
            for stat, base in pairs(item.magazine.base) do
                local field = get_field(base.table, base.record, base.offset, base.storage, base.stock)
                if #field.users == 0 then field.users[1] = item.name .. '.' .. stat end
                local entry = desired[field.key]
                if not entry then
                    entry = { field = field, value = item.stats[stat].field.stock, sources = {}, base = true }
                    desired[field.key] = entry
                end
                entry.group, entry.order = group, 1
            end
        end
        local switch = get_field('ComponentEntityDeltaStorage', 'components', magazine.run_at, 'u32', magazine.run_count)
        switch.exact = true
        desired[switch.key] = { field = switch, value = 0, sources = {}, base = true, group = group, order = 2 }
    end
    -- explosions of their own: order 1 = the borrowed row (a copy of the item's row, pointing at the
    -- damage row of its own), order 2 = the switches that make the item use it
    local function copy_explosion(source, target, damage, group)
        local from, to = ROWS['ExplosionSettings|' .. source], ROWS['ExplosionSettings|' .. target]
        local live = LIVE_WORDS.ExplosionSettings or {}
        for offset = 4, SPECS.ExplosionSettings.stride - 4, 4 do
            local field = get_field('ExplosionSettings', tostring(target), offset, 'u32', hex_word(to, offset))
            local value = hex_word(from, offset)
            if live[offset] then
                -- part of an array head: an address, only known in memory. Copied from the source row.
                field.exact, field.live = nil, get_field('ExplosionSettings', tostring(source), offset, 'u32', value)
            else
                field.exact, field.live = true, nil
                if offset == 4 and damage then value = damage end
            end
            local entry = desired[field.key]
            if not entry then
                entry = { field = field, value = value, sources = {}, base = true }
                desired[field.key] = entry
            end
            entry.group, entry.order = group, 1
        end
    end
    for _, a in ipairs(blasts) do
        local b = a.blast
        local function switch(field, value)
            field.exact = true
            desired[field.key] = { field = field, value = value, sources = { a.request }, base = true, group = a.group,
                                   order = 2, needs_index = (a.new_damage ~= nil or b.kind == 'P') or nil }
        end
        if a.new_explosion then
            copy_explosion(b.explosion, a.new_explosion, a.new_damage, a.group)
            for _, s in ipairs(b.switches) do
                if b.kind == 'P' then
                    switch(get_field(own_name('ProjectileSettings'), string.format('%.0f', a.takeover.new_projectile),
                                     s.offset, 'u32', b.explosion), a.new_explosion)
                else
                    switch(get_field(s.table, a.item.entity, s.offset, 'u32', b.explosion), a.new_explosion)
                end
            end
        elseif a.new_damage then
            switch(get_field('ExplosionSettings', tostring(b.explosion), 4, 'u32', b.damage), a.new_damage)
        end
    end
    -- own bullets: copy the weapon's round into the spare rows, then point the weapon at them.
    -- order 1 = the rows, order 2 = the switches (only thrown when every row field is in place).
    for item, request in pairs(own_bullet) do
        local t, group = request.takeover, item.name
        local function want(field, value, order)
            field.exact = true
            local entry = desired[field.key]
            if not entry then
                entry = { field = field, value = value, sources = { request }, base = true }
                desired[field.key] = entry
            end
            entry.group, entry.order = group, order
            if order == 2 and t.fresh then entry.needs_index = true end
        end
        local function copy_row(table_name, source, target, size, patch_at, patch_value)
            local from, to = ROWS[table_name .. '|' .. source], ROWS[table_name .. '|' .. target]
            for offset = 4, size - 4, 4 do
                local value = hex_word(from, offset)
                if offset == patch_at then value = patch_value end
                want(get_field(table_name, tostring(target), offset, 'u32', hex_word(to, offset)), value, 1)
            end
        end
        if t.fresh then
            -- the row of our own already is a copy; its damage row id is the one field we insist on
            want(get_field(own_name('ProjectileSettings'), string.format('%.0f', t.new_projectile), OWN_DAMAGE_AT, 'u32',
                           t.new_damage), t.new_damage, 1)
        else
            copy_row('ProjectileSettings', t.src_projectile, t.new_projectile, SPECS.ProjectileSettings.stride,
                     OWN_DAMAGE_AT, t.new_damage)
            copy_row('DamageSettings', t.src_damage, t.new_damage, SPECS.DamageSettings.stride, -1, 0)
        end
        if t.base_projectile then
            want(get_field('ProjectileWeaponComponentData', item.entity, 0, 'u32', t.base_projectile),
                 t.new_projectile, 2)
        end
        -- every other place of the item's own records that names a round (belt pattern, strike component)
        for _, s in ipairs(t.fresh and item.switches or {}) do
            local new = t.new_projectile
            if s.projectile ~= t.src_projectile then new = t.rounds and t.rounds[s.projectile] end
            if new then want(get_field(s.table, item.entity, s.offset, 'u32', s.projectile), new, 2) end
        end
        if item.ammo_delta then
            want(get_field('ComponentEntityDeltaStorage', 'data', item.ammo_delta.offset, 'u32',
                           item.ammo_delta.expected), t.new_projectile, 2)
        end
    end
end

local function load_config()
    local text = read_file(MOD.config)
    if text == nil then
        write_file(MOD.config, TEMPLATE)
        text = TEMPLATE
        log('config.txt did not exist: template written')
    end
    config.text = text
    build_desired(text)
    local accepted = 0
    for _ in pairs(desired) do accepted = accepted + 1 end
    state.reloads = state.reloads + 1
    state.report_pending = true
    log('#' .. state.reloads .. ' config loaded: ' .. #config.requests .. ' lines, ' .. accepted .. ' values to set')
end

local own_bullet_state   -- defined with sync(), below

-- STATUS.txt only shows the latest state; the log keeps what every reload did.
local function log_results()
    state.report_pending = false
    local tag = '#' .. state.reloads .. ' '
    for _, request in ipairs(config.requests) do
        local head = tag .. '[' .. request.category .. ': ' .. request.item .. '] ' .. request.text
        if request.status ~= 'accepted' then
            log(head .. ' -> ' .. tostring(request.status) .. ': ' .. tostring(request.reason))
        elseif request.own_item then
            local s, in_place, total, note = own_bullet_state(request.own_item.name)
            log(head .. ' -> own bullet ' .. s .. ' (' .. in_place .. ' of ' .. total .. ' fields)'
                .. (note and (' ' .. note) or ''))
        elseif request.blast then
            local s, in_place, total, note = own_bullet_state(request.blast.group)
            log(head .. ' -> own explosion ' .. s .. ' (' .. in_place .. ' of ' .. total .. ' fields)'
                .. (note and (' ' .. note) or ''))
        else
            for _, target in ipairs(request.targets) do
                local entry = applied[target.field.key]
                log(head .. ' -> ' .. target.stat .. ' = ' .. target.text .. (target.own and ' (own row) ' or ' ')
                    .. (entry and entry.state or 'waiting') .. (entry and entry.note and (' (' .. entry.note .. ')') or ''))
            end
        end
    end
end

-- ---------------------------------------------------------------- applying

local function needed_tables()
    local needed = {}
    for _, entry in pairs(desired) do needed[entry.field.table] = true end
    for _, entry in pairs(applied) do needed[entry.field.table] = true end
    return needed
end

local function missing_tables()
    local missing = {}
    for name in pairs(needed_tables()) do
        local usable = false
        for _, block in ipairs(SPECS[name].blocks) do
            if not block.problem then usable = true end
        end
        if not usable then missing[#missing + 1] = name end
    end
    table.sort(missing)
    return missing
end

-- Writes one value into one copy: checks, write, read back. -> true, or false + reason
local function write_checked(address, field, value)
    local bits = encode(value, field.storage)
    if bits == nil then return false, 'value cannot be stored' end
    local present, protection, shared = A.page(address)
    if not present then
        A.u32(address)                   -- not in the working set: reading the value brings the page back
        present, protection, shared = A.page(address)
    end
    if not present or shared then return false, 'memory page is not present or not private' end
    local unlocked = false
    if protection == PAGE_READONLY then
        -- In game the component tables (fire rate, handling, magazines...) are in read-only pages.
        if address % 4096 > 4092 or not A.protect(address, PAGE_READWRITE) then
            return false, 'the read-only page could not be made writable'
        end
        unlocked = true
        state.unlocks = state.unlocks + 1
    elseif protection ~= PAGE_READWRITE then
        return false, 'memory page is not writable (protection ' .. tostring(protection) .. ')'
    end
    local wrote = A.write_u32(address, bits)
    if unlocked then
        -- back to read-only whatever happened, and make sure it really is
        local restored = A.protect(address, PAGE_READONLY)
        local _, now = A.page(address)
        if not restored or now ~= PAGE_READONLY then
            state.left_open = state.left_open + 1
            state.errors = state.errors + 1
            log('page of ' .. hex(address) .. ' could not be put back to read-only')
        end
    end
    if not wrote then return false, 'the write was refused by Windows' end
    state.writes = state.writes + 1
    local back = read_field(address, field.storage)
    if not same_value(field.storage, back, value) then
        return false, 'read-back mismatch: wrote ' .. show(value, field.storage) .. ', read ' .. show(back, field.storage)
    end
    return true
end

-- Brings one field to `value` in every copy of its table (value nil: back to the original).
local function sync_field(entry, value)
    local field, spec = entry.field, SPECS[entry.field.table]
    state.step = 'applying ' .. field.table
    local range = nil
    for _, user in ipairs(field.users) do range = range or RANGES[user:match('%.(.+)$')] end
    local seen, done, waiting, absent = {}, 0, 0, 0
    for _, block in ipairs(spec.blocks) do
        seen[block.address] = true
        if parse_block(block) then
            local address = field_address(block, field)
            if address then
                local copy = entry.copies[block.address]
                local current = read_field(address, field.storage)
                if current == nil then
                    entry.note = 'value unreadable at ' .. hex(address)
                else
                    if not copy then
                        -- first touch of this copy: remember what the game had
                        copy = { address = address, original = current, block = block }
                        if not same_value(field.storage, current, field.stock) then
                            copy.foreign = true   -- not the game's stock value: another mod, or an update
                        end
                        entry.copies[block.address] = copy
                    end
                    local target = value
                    if target == nil then
                        target = copy.original
                    elseif field.live then
                        -- the value is whatever the row it is copied from holds in this copy of the table
                        local source = field_address(block, field.live)
                        target = source and A.u32(source)
                    end
                    if target == nil then
                        entry.note = 'the row to copy from cannot be read'
                    elseif same_value(field.storage, current, target) then
                        copy.value = target
                        done = done + 1
                    elseif field.exact and not copy.written and not same_value(field.storage, current, field.stock) then
                        entry.note = 'unexpected content ' .. show(current, field.storage) .. ' (expected '
                            .. show(field.stock, field.storage) .. '); not touched'
                    elseif range and (current < range.min - 0.5 or current > range.max + 0.5)
                        and not same_value(field.storage, current, field.stock) then
                        entry.note = 'current value ' .. show(current, field.storage) .. ' is implausible; not touched'
                    else
                        local ok, why = write_checked(address, field, target)
                        if ok then
                            done = done + 1
                            if copy.written then state.rewrites = state.rewrites + 1 end
                            copy.written, copy.value = value ~= nil, target
                            if value == nil then state.restores = state.restores + 1 end
                        else
                            entry.note = why
                            state.errors = state.errors + 1
                            log(field.key .. ' at ' .. hex(address) .. ': ' .. why)
                        end
                    end
                end
            else
                absent = absent + 1
            end
        else
            waiting = waiting + 1
        end
        pause()
    end
    -- Several blocks of one type are either copies of one table or its groups (stratagems): the record
    -- has to be in at least one of them.
    if absent > 0 and done == 0 and waiting == 0 and not entry.note and next(entry.copies) == nil then
        entry.note = 'record not found in the table'
    end
    for address in pairs(entry.copies) do
        if not seen[address] then entry.copies[address] = nil end   -- that copy is gone
    end
    entry.done = done
    return done
end

-- Makes memory match `desired`: sets what is asked for, restores what no longer is.
local function sync()
    local function apply(key, want)
        local entry = applied[key]
        if not entry then
            entry = { field = want.field, copies = {} }
            applied[key] = entry
        end
        entry.value, entry.sources, entry.note, entry.order = want.value, want.sources, nil, want.order
        local done = sync_field(entry, want.value)
        entry.state = done > 0 and not entry.note and 'applied' or (entry.note and 'failed' or 'waiting')
    end
    local function restore(key, entry)
        entry.note = nil
        local copies = 0
        for _ in pairs(entry.copies) do copies = copies + 1 end
        sync_field(entry, nil)
        if not entry.note or copies == 0 then applied[key] = nil
        else entry.state = 'restore failed' end
    end
    -- 1. take switches back first: a weapon must never point at a row we are about to restore
    for key, entry in pairs(applied) do
        if not desired[key] and entry.order == 2 then restore(key, entry) end
    end
    -- 2. plain values and the rows of own bullets
    local ready = {}
    for key, want in pairs(desired) do
        if want.order ~= 2 then
            apply(key, want)
            if want.group and applied[key].state ~= 'applied' then ready[want.group] = false end
        end
    end
    -- 3. switches, only for weapons whose rows are completely in place
    local index_checked, index_ok = false, nil
    for key, want in pairs(desired) do
        if want.order == 2 then
            if want.needs_index and not index_checked then
                index_checked = true
                index_ok, own.index_note = true, nil
                for _, name in ipairs(OWN_TABLES) do
                    local ok, why = own_index_ok(name)
                    if not ok then
                        index_ok, own.index_note = ok, why
                        break
                    end
                end
            end
            if ready[want.group] == false then
                want.blocked = true
            elseif want.needs_index and not index_ok then
                want.blocked = true      -- never use a new id while the index is not proven
            else
                want.blocked = nil
                apply(key, want)
            end
        end
    end
    -- 4. everything else that is no longer wanted
    for key, entry in pairs(applied) do
        if not desired[key] then restore(key, entry) end
    end
end

-- State of one weapon's own bullet: 'active' | 'waiting' | 'failed', fields in place, fields total, note
own_bullet_state = function(group)
    local total, in_place, failed, note = 0, 0, false, nil
    for key, want in pairs(desired) do
        if want.group == group then
            total = total + 1
            local entry = applied[key]
            if entry and entry.state == 'applied' and not want.blocked then
                in_place = in_place + 1
            elseif entry and entry.state == 'failed' then
                failed, note = true, note or (want.field.key .. ': ' .. tostring(entry.note))
            end
        end
    end
    if failed then return 'failed', in_place, total, note end
    if in_place == total then return 'active', in_place, total end
    return 'waiting', in_place, total
end

-- Cheap check of everything applied: block still there, value still ours. -> 'ok' | 'lost' | 'changed'
local function recheck()
    local result = 'ok'
    for _, entry in pairs(applied) do
        for _, copy in pairs(entry.copies) do
            if not valid_block(copy.block) then
                return 'lost'
            end
            -- only values we actually wrote can be "changed back"; a refused write is not retried
            if entry.value ~= nil and copy.written then
                local current = read_field(copy.address, entry.field.storage)
                local expected = entry.value
                if entry.field.live then expected = copy.value end
                if not same_value(entry.field.storage, current, expected) then result = 'changed' end
            end
        end
        pause()
    end
    return result
end

-- ---------------------------------------------------------------- reports
local function count_states()
    local counts = { applied = 0, waiting = 0, failed = 0, rejected = 0, lines = 0 }
    for _, request in ipairs(config.requests) do
        if request.status ~= 'replaced' then counts.lines = counts.lines + 1 end
        if request.status == 'rejected' then counts.rejected = counts.rejected + 1 end
    end
    local groups = {}
    for key, want in pairs(desired) do
        if want.group then groups[want.group] = true end
        if not want.base then
            local entry = applied[key]
            local s = entry and entry.state or 'waiting'
            if s == 'applied' then counts.applied = counts.applied + 1
            elseif s == 'waiting' then counts.waiting = counts.waiting + 1
            else counts.failed = counts.failed + 1 end
        end
    end
    counts.own, counts.magazines, counts.blasts = 0, 0, 0
    for group in pairs(groups) do
        local s = own_bullet_state(group)
        if s == 'active' then
            if group:sub(1, 9) == 'magazine:' then counts.magazines = counts.magazines + 1
            elseif group:sub(1, 6) == 'blast:' then counts.blasts = counts.blasts + 1
            else counts.own = counts.own + 1 end
        elseif s == 'waiting' then counts.waiting = counts.waiting + 1
        else counts.failed = counts.failed + 1 end
    end
    return counts
end

local function build_status()
    local L = {}
    local function add(text) L[#L + 1] = text end
    local counts = count_states()
    local verdict
    if state.phase == 'gave_up' then
        verdict = 'FAILED - ' .. tostring(state.failure)
    elseif build.state == 'unchecked' then
        verdict = 'WAITING - checking the game build (nothing written yet)'
    elseif build.state ~= 'verified' then
        verdict = 'REFUSED - this game build is not one this version was verified on; nothing was written'
    elseif not config.enabled then
        verdict = 'DISABLED - enabled = false in config.txt; all values are the game\'s own'
    elseif counts.applied + counts.own + counts.blasts + counts.waiting + counts.failed
        + counts.rejected == 0 then
        verdict = 'OK - no changes configured'
    elseif counts.waiting + counts.failed + counts.rejected == 0 then
        verdict = 'OK - ' .. counts.applied .. ' values applied'
            .. (counts.own > 0 and (', ' .. counts.own .. ' weapons on their own bullet') or '')
            .. (counts.magazines > 0 and (', ' .. counts.magazines .. ' magazines switched to the weapons\' own values') or '')
            .. (counts.blasts > 0 and (', ' .. counts.blasts .. ' explosions of their own') or '')
    else
        verdict = string.format('PARTIAL - %d values applied, %d waiting for their table, %d failed, %d config lines rejected',
                                counts.applied, counts.waiting, counts.failed, counts.rejected)
    end
    state.verdict = verdict
    add(verdict)
    add(MOD.title .. ' v' .. MOD.version)
    add(string.format('phase=%s frame=%d errors=%d writes=%d restores=%d rewrites=%d reloads=%d', state.phase,
                      state.frame, state.errors, state.writes, state.restores, state.rewrites, state.reloads))
    add(string.format('read-only pages opened for a write=%d, not closed again=%d', state.unlocks, state.left_open))
    local loader = rawget(_G, 'CowboyBingusModLoader')
    add('loader: ' .. (type(loader) == 'table' and ('api=' .. tostring(loader.api) .. ' version=' .. tostring(loader.version))
                       or 'CowboyBingusModLoader global not found'))
    if rawget(_G, 'HD2StatTunerRecon') then add('note: the recon build is also installed; remove it, both write STATUS.txt') end
    add('')
    add('[build] ' .. build.state .. (build.label and (': ' .. build.label) or ''))
    for _, m in ipairs(build.modules) do
        add(string.format('%s: size=%s sha256=%s%s', m.name, tostring(m.file_size), tostring(m.sha256),
                          m.note and ('  note: ' .. m.note) or ''))
    end
    if build.state == 'unknown' then
        add('known builds:')
        for _, known in ipairs(BUILDS) do add('  ' .. known.label .. ' exe=' .. known.exe .. ' dll=' .. known.dll) end
    end
    add('')
    add(string.format('[settings] enabled=%s reload_key=%s menu_key=%s auto_reload_seconds=%s rescan_seconds=%s own_rows=%s',
                      tostring(config.enabled), config.reload_key, config.menu_key, tostring(config.auto_reload),
                      tostring(config.rescan), config.own_rows and 'auto' or 'off'))
    local from_menu = 0
    for _ in pairs(overrides) do from_menu = from_menu + 1 end
    if from_menu > 0 then
        add('preset "' .. tostring(preset_name or 'Default') .. '": ' .. from_menu
            .. ' values set through the in-game menu (they win over config.txt)')
    end
    for _, problem in ipairs(config.problems) do add('config problem: ' .. problem) end
    if own.state ~= 'unused' then
        add('')
        add('[own rows] ' .. own.state .. (own.note and (': ' .. own.note) or ''))
        if own.block then
            add('block ' .. hex(own.block) .. ' size ' .. OWN_SIZE)
            for _, name in ipairs(OWN_TABLES) do
                local t = own.tables[name]
                add(string.format('%s: game index %s, first new id %.0f, rows in use %d of %d', name, hex(t.index),
                                  t.first_id, t.count, OWN_CAPACITY))
            end
            for _, user in ipairs(own.order) do
                add(string.format('  %s: %s id %.0f, row at %s (copy of row %d), slot at %s', user.name, user.table, user.id,
                                  hex(user.row), user.source, hex(user.slot)))
            end
        end
    end
    if #spare.order > 0 then
        add('')
        add('[borrowed rows] explosion rows that may be borrowed: ' .. table.concat(SPARE.ExplosionSettings or {}, ' '))
        for _, user in ipairs(spare.order) do
            add(string.format('  %s: %s row %d (as a copy of row %d)', user.name, user.table, user.id, user.source))
        end
    end
    add('')
    add('[tables] needed by the config: name copies | address size origin')
    local needed, names = needed_tables(), {}
    for name in pairs(needed) do names[#names + 1] = name end
    table.sort(names)
    for _, name in ipairs(names) do
        local spec = SPECS[name]
        add(name .. ' copies=' .. #spec.blocks)
        for n, block in ipairs(spec.blocks) do
            -- (armor kits and passives are a block each, hundreds of them: the first few say enough)
            if spec.shape ~= 'S' or n <= 4 or block.problem then
                add(string.format('  %s size=%d origin=%s%s', hex(block.address), block.size, tostring(block.origin),
                                  block.problem and (' PROBLEM: ' .. block.problem) or ''))
            end
        end
    end
    if #names == 0 then add('none') end
    add(string.format('search: passes=%d allocations=%d last_pass_seconds=%.2f slowest_query_ms=%.2f at %s',
                      search.passes, search.allocations, search.seconds, search.slowest_query * 1000,
                      hex(search.slowest_at)))
    add('')
    add('[config lines]')
    for _, request in ipairs(config.requests) do
        local head = string.format('line %d [%s: %s] %s', request.line, request.category, request.item, request.text)
        if request.status ~= 'accepted' then
            add(head .. ' -> ' .. tostring(request.status):upper() .. ': ' .. tostring(request.reason))
        elseif request.own_item then
            local t = request.takeover
            local s, in_place, total, note = own_bullet_state(request.own_item.name)
            if t.fresh and s == 'waiting' then note = note or own.index_note end
            local new = t.fresh and 'NEW ID ' or ''
            add(string.format('%s -> OWN BULLET %s: projectile row %d -> %s%.0f, damage row %d -> %s%.0f (%d of %d fields in place)%s',
                head, s:upper(), t.src_projectile, new, t.new_projectile, t.src_damage, new, t.new_damage,
                in_place, total, note and ('  ' .. note) or ''))
        elseif request.blast then
            local a = request.blast
            local s, in_place, total, note = own_bullet_state(a.group)
            if s == 'waiting' then note = note or own.index_note end
            add(string.format('%s -> OWN EXPLOSION %s: %s%s (%d of %d fields in place)%s', head, s:upper(),
                a.new_explosion and string.format('explosion row %d -> borrowed row %d', a.blast.explosion, a.new_explosion)
                    or string.format('explosion row %d is its own', a.blast.explosion),
                a.new_damage and string.format(', damage row %d -> NEW ID %.0f', a.blast.damage, a.new_damage) or '',
                in_place, total, (note or a.problem) and ('  ' .. tostring(note or a.problem)) or ''))
        else
            add(head .. (request.warning and ('   WARNING: ' .. request.warning) or '')
                .. (request.yielded and ('   (set by their own lines instead: ' .. request.yielded .. ')') or ''))
            for _, target in ipairs(request.targets) do
                local entry, field = applied[target.field.key], target.field
                local copies, originals, foreign = 0, {}, false
                if entry then
                    for _, copy in pairs(entry.copies) do
                        copies = copies + 1
                        originals[show(copy.original, field.storage)] = true
                        foreign = foreign or copy.foreign
                    end
                end
                local was = {}
                for text in pairs(originals) do was[#was + 1] = text end
                table.sort(was)
                local others = {}
                for _, user in ipairs(field.users) do
                    if user ~= request.item:lower() .. '.' .. target.stat and #others < 12 then others[#others + 1] = user end
                end
                add(string.format('  %s: %s -> %s  %s  copies=%d%s%s%s%s%s', target.stat,
                    target.was_text or (#was > 0 and table.concat(was, '/') or show(field.stock, field.storage)),
                    target.text .. (target.own and ' (own row)' or ''),
                    (entry and entry.state or 'waiting'):upper(), copies,
                    entry and entry.note and ('  (' .. entry.note .. ')') or '',
                    foreign and '  (the value was not the game\'s stock value before we changed it)' or '',
                    target.attachment and '  (value of the default attachment)' or '',
                    target.magazine and ('  (in the weapon\'s own record; the magazine attachment\'s values are '
                        .. (own_bullet_state('magazine:' .. target.magazine.magazine.resource) == 'active'
                            and 'switched off)' or 'NOT switched off yet)')) or '',
                    #others > 0 and ('  also affects: ' .. table.concat(others, ', ')
                                     .. (#field.users - 1 > #others and ', ...' or '')) or ''))
            end
        end
    end
    if #config.requests == 0 then add('none') end
    local leftovers = {}
    for key, entry in pairs(applied) do
        if not desired[key] then leftovers[#leftovers + 1] = key .. ': ' .. tostring(entry.state) .. ' (' .. tostring(entry.note) .. ')' end
    end
    if #leftovers > 0 then
        add('')
        add('[not restored]')
        table.sort(leftovers)
        for _, line in ipairs(leftovers) do add(line) end
    end
    add('')
    add(string.format('[cost] worst_frame_ms=%.2f (during: %s) busy_frames=%d busy_seconds=%.2f',
                      state.worst_frame * 1000, tostring(state.worst_step), state.busy_frames, state.busy_seconds))
    return table.concat(L, '\r\n') .. '\r\n'
end

local last_status = nil
local function write_status(force)
    local ok, text = pcall(build_status)
    if not ok then
        log('status: ' .. tostring(text))
        text = 'FAILED - could not build the status report: ' .. tostring(text) .. '\r\n'
            .. MOD.title .. ' v' .. MOD.version .. '\r\n'
    end
    -- the cost line changes all the time: only rewrite the file when something else did
    local stable = text:gsub('%[cost%][^\r\n]*', ''):gsub('frame=%d+', '')
    if force or stable ~= last_status then
        last_status = stable
        write_file(MOD.status, text)
    end
    if log_dirty then flush_log() end
end

-- Written a few items at a time, so that no frame pays for the whole file.
local function write_catalog()
    local dir = ensure_out_dir()
    local title = MOD.title .. ' v' .. MOD.version .. ' catalog'
    local existing = dir and io.open(dir .. '\\' .. MOD.catalog, 'rb')
    if existing then
        -- the catalog only changes with the version: an up-to-date one is left alone
        local first = existing:read('*l')
        existing:close()
        if first and first:gsub('%s+$', '') == title then return end
    end
    local handle = dir and io.open(dir .. '\\' .. MOD.catalog, 'wb')
    if not handle then return end
    handle:write(table.concat({ MOD.title .. ' v' .. MOD.version .. ' catalog',
        'category | item | stat | game value | allowed range | notes',
        'Use these names in config.txt:  [category: item]  then  stat = value', '', '' }, '\r\n'))
    for index = 0, #ITEMS do
        local item = ITEMS[index]
        if item then
            -- (written piece by piece: a string built only to be written is one more string for the
            -- interpreter to keep track of, and there would be thirty thousand of them)
            handle:write('[', item.category, ': ', item.name, ']', item.display and '   # ' or '', item.display or '', '\r\n')
            for n, stat in ipairs(item.stat_order) do
                -- (an enemy with all its parts has 180 values)
                if n % 12 == 0 then pause() end
                local entry, range = item.stats[stat], RANGES[stat]
                handle:write('  ', stat, ' = ', show(entry.field.stock, entry.field.storage), '   (', show(range.min, 'f32'),
                             ' .. ', show(range.max, 'f32'), range.integer and ', whole numbers)' or ')')
                local shared = #entry.field.users > 1
                if entry.attachment then
                    handle:write('   # value of the default attachment: another attachment on the weapon replaces it',
                                 shared and '; ' or '')
                elseif shared then
                    handle:write('   # ')
                end
                if shared then handle:write('shared with ', tostring(#entry.field.users - 1), ' other') end
                handle:write('\r\n')
            end
            if item.takeover or (item.blasts and item.blasts[1].kind == 'C') then
                handle:write('  blast_from = <item>   # explode like another item, by its name (frag_grenade, '
                    .. 'gas_grenade, grenade_launcher...)\r\n')
            end
            if item.takeover then
                handle:write('  own_bullet = false   (', item.takeover.new_projectile ~= 0 and 'true / ' or '',
                    'false / new)   # happens by itself when a projectile or damage stat of this weapon is set: '
                    .. 'the weapon gets rows of its own, so the change reaches this weapon only. false: keep the '
                    .. 'shared rows (the change then also reaches every weapon listed under "also affects")\r\n')
            end
            handle:write('\r\n')
            -- hand every item to the system at once: one large flush at the end cost a 9..15 ms frame in game
            handle:flush()
        end
        pause()
    end
    handle:write('Shortcuts: ap, blast_ap (every angle that is not 0), recoil, recoil_h, recoil_v, spread, magazine, '
        .. 'spare_magazines, carried\r\n')
    handle:close()
end

-- ---------------------------------------------------------------- research (v1.1.1)
-- Read-only. Once per start, RESEARCH.txt is written:
--   * every row of the status effect table. The table is not in the offline data, and the recon build
--     of v0.1.0 wrote out 8 of its 71 rows only, so the game's own duration of the others is not known;
--   * what this build of the engine offers for fonts and input (names and yes / no, nothing is called
--     but Application.can_get, which the menu uses as well).
-- Off unless config.txt says `[settings] research = true` (it was on by default in v1.1.1 .. v1.1.11,
-- the test builds).
local research = { pending = true, tries = 0 }
research.fonts = { 'core/performance_hud/debug', 'core/editor_slave/gui/arial', 'gui/fonts/arial',
    'content/fonts/core_sans', 'content/fonts/core_sans_curved', 'content/fonts/cyborg_style',
    'content/fonts/cyborg_style_terminal_layer', 'content/fonts/fallback', 'content/fonts/runtime_font',
    'content/fonts/runtime_font_curved', 'content/fonts/runtime_font_terminal_layer', 'content/fonts/samples',
    'content/fonts/samples_curved', 'content/fonts/samples_terminal_layer' }
research.types = { 'runtime_font', 'runtime_font_atlas', 'runtime_font_atlases', 'font_atlas', 'font_material',
                   'material', 'texture' }
research.engine = { Keyboard = { 'down_threshold', 'set_down_threshold', 'keystrokes', 'button', 'pressed' },
    Mouse = { 'down_threshold', 'set_down_threshold', 'axis', 'button' },
    Window = { 'set_show_cursor', 'show_cursor', 'set_clip_cursor', 'set_mouse_focus', 'has_focus' },
    Gui = { 'has_all_glyphs', 'text_extents', 'word_wrap', 'material' },
    Application = { 'can_get', 'user_setting', 'back_buffer_size' }, Localizer = { 'lookup', 'set_language' },
    Input = { 'event_queue' } }

-- (kept in one table: the main chunk of a Lua file may hold 200 local variables, and this file is near)
function research.run()
    research.tries = research.tries + 1
    local L = { MOD.title .. ' v' .. MOD.version .. ' research (read-only)', 'build: ' .. tostring(build.label or build.state),
                '' }
    local spec = SPECS['StatusEffectSettings']
    if spec and #spec.blocks == 0 then
        state.step = 'research: searching for the status table'
        find_tables()
    end
    local block = spec and spec.blocks[1]
    local rows = 0
    if block and parse_block(block) then
        local stride = spec.stride
        L[#L + 1] = '[status effects] ' .. block.count .. ' rows of ' .. stride .. ' bytes at ' .. hex(block.records_at)
        L[#L + 1] = '# id | debug name | +32 | +36 | +40 (duration) | the whole row'
        for row = 0, block.count - 1 do
            state.step = 'research: status row ' .. row
            local at = block.records_at + row * stride
            if A.read(at, stride) then
                local bytes, parts = A.buffer, {}
                for i = 0, stride - 1 do parts[i + 1] = string.format('%02X', bytes[i]) end
                local raw = table.concat(parts)
                local id = A.u32(at)
                local floats = {}
                for n, offset in ipairs({ 32, 36, 40 }) do
                    local bits = A.u32(at + offset)
                    floats[n] = bits and string.format('%g', bits_to_f32(bits)) or '?'
                end
                -- the debug name: a pointer to a C string at +8
                local name, pointer = '?', A.u64(at + 8)
                if pointer and pointer > 0x10000 and A.read(pointer, 64) then
                    local chars = {}
                    for i = 0, 63 do
                        local c = A.buffer[i]
                        if c == 0 then break end
                        chars[#chars + 1] = (c >= 32 and c < 127) and string.char(c) or '?'
                    end
                    name = table.concat(chars)
                end
                L[#L + 1] = table.concat({ tostring(id), name, floats[1], floats[2], floats[3], raw }, '|')
                rows = rows + 1
            else
                L[#L + 1] = '# row ' .. row .. ' unreadable'
            end
            pause()
        end
    else
        L[#L + 1] = '[status effects] the table was not found (try ' .. research.tries .. ')'
    end
    L[#L + 1] = ''
    local S = rawget(_G, 'stingray')
    if type(S) == 'table' then
        L[#L + 1] = '[engine] functions that are there'
        local tables = {}
        for name in pairs(research.engine) do tables[#tables + 1] = name end
        table.sort(tables)
        for _, name in ipairs(tables) do
            local found = {}
            for _, fn in ipairs(research.engine[name]) do
                found[#found + 1] = fn .. '=' .. ((type(S[name]) == 'table' and type(S[name][fn]) == 'function') and 'yes' or 'no')
            end
            L[#L + 1] = name .. ': ' .. table.concat(found, ' ')
        end
        L[#L + 1] = ''
        L[#L + 1] = '[fonts] Application.can_get("font", name)'
        if type(S.Application) == 'table' and type(S.Application.can_get) == 'function' then
            log('research: about to use Application.can_get("font", name)')
            flush_log()
            for _, font in ipairs(research.fonts) do
                local asked, there = pcall(S.Application.can_get, 'font', font)
                L[#L + 1] = font .. ': ' .. (asked and tostring(there) or ('error ' .. tostring(there)))
            end
        else
            L[#L + 1] = 'the engine cannot be asked'
        end
        -- The same names under the other resource types the name list has for fonts. Seen in game: with
        -- the game set to Chinese no "font" for Chinese is loaded, so it is drawn with something else.
        -- A type the engine does not know has not been asked for before: a file marks the try, and a
        -- start that finds the mark (the game closed there) leaves this part out.
        L[#L + 1] = ''
        L[#L + 1] = '[resources] Application.can_get(type, name): only what is there is listed'
        if type(S.Application) ~= 'table' or type(S.Application.can_get) ~= 'function' then
            L[#L + 1] = 'the engine cannot be asked'
        elseif read_file('RESEARCH-running.txt') then
            L[#L + 1] = 'left out: the game closed the last time this was asked (' .. trim(read_file('RESEARCH-running.txt')) .. ')'
        else
            for _, kind in ipairs(research.types) do
                write_file('RESEARCH-running.txt', kind .. '\r\n')
                log('research: about to use Application.can_get("' .. kind .. '", name)')
                flush_log()
                local there_list = {}
                for _, font in ipairs(research.fonts) do
                    local asked, there = pcall(S.Application.can_get, kind, font)
                    if not asked then there_list[#there_list + 1] = font .. ' (error ' .. tostring(there) .. ')'
                    elseif there then there_list[#there_list + 1] = font end
                end
                L[#L + 1] = kind .. ': ' .. (#there_list > 0 and table.concat(there_list, ', ') or 'none')
                pause()
            end
            local dir = ensure_out_dir()
            if dir then os.remove(dir .. '\\RESEARCH-running.txt') end
        end
    else
        L[#L + 1] = '[engine] no stingray table here'
    end
    write_file('RESEARCH.txt', table.concat(L, '\r\n') .. '\r\n')
    if rows > 0 or research.tries >= 3 then
        research.pending = false
        log('research: RESEARCH.txt written, ' .. rows .. ' status rows')
    end
end

-- ---------------------------------------------------------------- the worker
local wake = { at = 0, reload = false, config_check_at = 0 }

local function sleep(seconds)
    wake.at = A.now() + seconds
    coroutine.yield()
end

local function worker_main()
    state.step = 'reading the built-in data'
    parse_data()
    state.phase, state.step = 'checking the build', 'hashing the game files'
    write_status(true)
    check_build()
    state.step = 'reading config.txt'
    load_config()
    state.step = 'writing catalog.txt'
    write_catalog()
    local backoff, next_rescan = 1, 0
    while true do
        if wake.reload then
            wake.reload = false
            state.step = 'reading config.txt'
            load_config()
            backoff = 1
        end
        if build.state ~= 'verified' then
            state.phase = 'refused'
            write_status()
            sleep(3600)
        else
            if config.research and research.pending then
                local ok_research, why_research = pcall(research.run)
                if not ok_research then
                    research.pending = research.tries < 3
                    log('research: ' .. tostring(why_research))
                end
            end
            local missing = missing_tables()
            local have_work = next(desired) ~= nil or next(applied) ~= nil
            local rescan_due = have_work and config.rescan > 0 and A.now() >= next_rescan
            if have_work and (#missing > 0 or state.lost or rescan_due) then
                state.phase, state.step = 'searching', 'searching for tables'
                find_tables()
                state.lost = false
                next_rescan = A.now() + (config.rescan > 0 and config.rescan or 0)
            end
            if have_work then
                state.phase, state.step = 'applying', 'applying values'
                sync()
                state.step = 'writing STATUS.txt'
            end
            if state.report_pending then
                local ok_report, why_report = pcall(log_results)
                if not ok_report then log('report: ' .. tostring(why_report)) end
            end
            missing = missing_tables()
            if not have_work then
                state.phase = 'idle'
                write_status()
                sleep(3600)
            elseif #missing > 0 then
                state.phase = 'waiting for tables'
                write_status()
                sleep(SEARCH_BACKOFF[math.min(backoff, #SEARCH_BACKOFF)])
                backoff = backoff + 1
            else
                backoff = 1
                state.phase = 'applied'
                write_status()
                -- asleep: only cheap read-backs until something needs attention
                while not wake.reload do
                    sleep(RECHECK_SECONDS)
                    if wake.reload then break end
                    state.step = 'rechecking applied values'
                    local result = recheck()
                    if result == 'lost' then
                        state.lost = true
                        log('a patched table is gone (map load?): searching again')
                        break
                    elseif result == 'changed' then
                        log('a patched value was changed back: applying again')
                        break
                    elseif config.rescan > 0 and A.now() >= next_rescan then
                        break
                    end
                end
            end
        end
    end
end

-- ---------------------------------------------------------------- per frame
local worker, key_was_down, last_key_reload = nil, false, -1000

local function request_reload()
    wake.reload, wake.at = true, 0
end

-- ---------------------------------------------------------------- in-game menu
-- A panel in the middle of the screen, drawn with the engine's own immediate-mode Gui (confirmed in
-- game by the drawing probe of v0.14.0). Keyboard only, every key can be changed on the Keys page.
-- Four pages: Items (the values), Presets, Keys, Language.
-- The menu is in one mode at a time, and a key does only what it means in that mode:
--   list     moving through the lists and changing values
--   text     a box is being typed into (search, a value, a preset's name): keys go to the text only
--   capture  the next key pressed is given to an action
--   confirm  a yes / no question
-- A change is an entry of `overrides` (the same path the API uses): it is applied by the engine like a
-- config line, wins over config.txt for that value, and is kept in the active preset's file.
local SETTINGS_FILE, PRESET_DIR, OLD_MENU_FILE = 'settings.txt', 'presets', 'menu.txt'
local KEY_VK = { UP = 0x26, DOWN = 0x28, LEFT = 0x25, RIGHT = 0x27, TAB = 0x09, ENTER = 0x0D, ESCAPE = 0x1B,
                 SPACE = 0x20, BACKSPACE = 0x08, DELETE = 0x2E, INSERT = 0x2D, HOME = 0x24, END = 0x23,
                 PAGE_UP = 0x21, PAGE_DOWN = 0x22, SHIFT = 0x10, CTRL = 0x11, ALT = 0x12, MINUS = 0xBD,
                 EQUALS = 0xBB, COMMA = 0xBC, PERIOD = 0xBE, SLASH = 0xBF, SEMICOLON = 0xBA, QUOTE = 0xDE,
                 LBRACKET = 0xDB, RBRACKET = 0xDD, BACKSLASH = 0xDC, GRAVE = 0xC0, ADD = 0x6B, SUBTRACT = 0x6D,
                 MULTIPLY = 0x6A, DIVIDE = 0x6F, DECIMAL = 0x6E }
for n = 1, 12 do KEY_VK['F' .. n] = 0x6F + n end
for code = 0x30, 0x39 do KEY_VK[string.char(code)] = code end
for code = 0x41, 0x5A do KEY_VK[string.char(code)] = code end
for n = 0, 9 do KEY_VK['NUMPAD' .. n] = 0x60 + n end
local KEY_ORDER = {}
for name in pairs(KEY_VK) do KEY_ORDER[#KEY_ORDER + 1] = name end
table.sort(KEY_ORDER)
-- what a key types into a box: { key, plain, with Shift }
local MENU_TYPED = { { 'SPACE', ' ', ' ' }, { 'MINUS', '-', '_' }, { 'SUBTRACT', '-', '-' }, { 'PERIOD', '.', '.' },
                     { 'DECIMAL', '.', '.' } }
for code = 0x30, 0x39 do
    MENU_TYPED[#MENU_TYPED + 1] = { string.char(code), string.char(code), string.char(code) }
    MENU_TYPED[#MENU_TYPED + 1] = { 'NUMPAD' .. (code - 0x30), string.char(code), string.char(code) }
end
for code = 0x41, 0x5A do
    MENU_TYPED[#MENU_TYPED + 1] = { string.char(code), string.char(code):lower(), string.char(code) }
end
