-- fonts of the game that may hold Chinese glyphs (names from the community's list of resource names);
-- one is only used when the engine says the resource is there. Seen in game (v1.1.2 .. v1.1.7): the
-- engine has none of these three. It has `content/fonts/samples`, which was on this list until v1.1.7:
-- a font of symbols, in which the whole menu came out as icons. So in the game as it is, the Language
-- page says that no font can draw Chinese.
-- What the research file of v1.1.9 found with the game set to Chinese: no resource of type "font" for it,
-- but a "runtime_font" named content/fonts/fallback and a material named content/fonts/runtime_font.
-- { resource type, font, material }
local MENU_FONTS_ZH = { { 'runtime_font', 'content/fonts/fallback', 'content/fonts/runtime_font' } }
local MENU_PRESET_ACTIONS = { 'Activate', 'Rename', 'Duplicate', 'Delete' }
local menu = { open = false, state = 'closed', page = 1, tab = 1, focus = 'items', item = {}, stat = {}, keys = {},
               toggle_down = false, loaded = false, filter = '', mode = 'list', bind = {}, lang = 'en',
               lang_saved = 'en', block = true, block_saved = true, presets = {}, preset_row = 1, preset_action = 1, key_row = 1,
               lang_row = 1, zh_fonts = {}, zh_font = nil, fold = {}, fold_version = 1 }

local function menu_key_of(item, stat) return item.category .. ':' .. item.name:lower() .. ':' .. stat end

-- The engine's functions are native: a wrong argument can close the game instead of raising a Lua error
-- (v0.15.0 in game: F9 closed the game, and nothing in the log said where). So the first time each
-- engine call is about to be made, a line goes to the log file and is written out at once.
local menu_trail = {}
local function menu_step(name)
    if menu_trail[name] then return end
    menu_trail[name] = true
    log('menu: about to use ' .. name)
    flush_log()
end

-- ---- text: Chinese takes two cells of width and three bytes a character
local function menu_cells(text)
    local n = 0
    for i = 1, #text do
        local b = text:byte(i)
        if b < 0x80 then n = n + 1 elseif b >= 0xC0 then n = n + 2 end
    end
    return n
end
local function menu_clip(text, cells)
    local n, i = 0, 1
    while i <= #text do
        local b = text:byte(i)
        local bytes = b < 0x80 and 1 or (b >= 0xF0 and 4 or (b >= 0xE0 and 3 or 2))
        local wide = b < 0x80 and 1 or 2
        if n + wide > cells then return text:sub(1, i - 1) end
        n, i = n + wide, i + bytes
    end
    return text
end

