-- Catalog names are display-only. The English data, order, search aliases and config keys stay intact.
function menu.name(text)
    if menu.lang ~= 'zh' then return text end
    if menu.names_zh[text] then return menu.names_zh[text] end
    local base, id = text:match('^(.-) %[(.-)%]$')
    if base then return menu.name(base) .. ' [' .. id .. ']' end
    local kind, hash = text:match('^(%a+)_([0-9a-f]+)$')
    if hash and #hash == 8 then
        local label = ({weapon = '未识别武器 ', body = '未识别机体 ', armor = '未识别护甲 ', pack = '未识别背包 '})[kind]
        if label then return label .. hash end
    end
    local row, values, ap = text:match('^Damage row (%d+): (.-), AP (.+)$')
    if row then return '伤害数据 ' .. row .. ': ' .. values .. ', 穿甲 ' .. ap end
    row, values, ap = text:match('^(%d+): (.-), AP (.+)$')
    if row then return row .. ': ' .. values .. ', 穿甲 ' .. ap end
    local body = text:match('^Body without a name: (.*)$')
    if body then return '未识别机体: ' .. menu.name(body) end
    local health, armor, parts = text:match('^health (.-), armor (.-), (.-) parts$')
    if health then return '生命 ' .. health .. ', 护甲 ' .. armor .. ', 部件 ' .. parts end
    return text
end

function menu.part_name(part)
    if menu.lang == 'zh' then return menu.parts_zh[part] or part end
    return part
end

-- Translate only the on-screen copy of engine messages. STATUS.txt and the public API keep English.
function menu.message(text)
    text = tostring(text or '')
    if menu.lang ~= 'zh' then return text end
    if MENU_ZH[text] then return MENU_ZH[text] end
    local a, b, c, d = text:match('^PARTIAL %- (%d+) values applied, (%d+) waiting for their table, (%d+) failed, (%d+) config lines rejected$')
    if a then return ('部分完成 - 已应用 %s 项，等待 %s 项，失败 %s 项，拒绝 %s 行配置'):format(a, b, c, d) end
    if text:match('^OK %- %d+ values applied') then
        local translated = text:gsub('^OK %- (%d+) values applied', '正常 - 已应用 %1 项')
        translated = translated:gsub(', (%d+) weapons on their own bullet', '，独立弹丸武器 %1 件')
        translated = translated:gsub(", (%d+) magazines switched to the weapons' own values", '，独立弹匣 %1 个')
        translated = translated:gsub(', (%d+) explosions of their own', '，独立爆炸 %1 项')
        return translated
    end
    a, b, c = text:match('^mags_start (%d+) is above mags_max (%d+): the game starts with (%d+)%. Set mags_max as well$')
    if a then return ('初始弹匣 %s 超过上限 %s，实际初始为 %s。请同时提高弹匣上限'):format(a, b, c) end
    local stat
    stat, a, b, c, d = text:match('^(%w+_?%w*) (%d+) is above (%d+): the game starts with (%d+), but a resupply fills up to (%d+) at most$')
    if stat then
        local label = stat == 'charges' and '携带次数' or '备弹上限'
        return ('%s %s 超过 %s，初始为 %s，补给最多恢复至 %s'):format(label, a, b, c, d)
    end
    local part, health, share, main = text:match('^part (.-) has (%d+) health and passes (%d+)%% of its damage on, the main health is (%d+):')
    if part then
        return ('%s生命 %s，传递 %s%% 伤害，主体生命 %s。载具会先损毁；提高主体生命或降低传递比例，或用 all_health 同步缩放'):format(menu.part_name(part), health, share, main)
    end
    local failure = text:match('^FAILED %- (.*)$')
    if failure then return '失败 - ' .. (MENU_ZH[failure] or failure) end
    return text
end

function menu.key_name(key)
    if menu.lang ~= 'zh' then return key end
    return menu.keys_zh[key] or key
end

-- the text of the menu in the chosen language
local function L(text)
    if menu.lang == 'zh' then return MENU_ZH[text] or text end
    return text
end

-- the names of the status effects, by the id a `status*_type` value holds (docs/STATUS-EFFECTS.md)
