    weight = 'Weight class (0 light, 1 medium, 2 heavy)', passive = 'Passive (its number in the Passives list)',
    speed_walk = 'Walking speed', speed_jog = 'Jogging speed', speed_sprint = 'Sprinting speed',
    speed_sprint_exerted = 'Sprinting speed, out of stamina', speed_crouch_walk = 'Crouched walking speed',
    speed_crouch_sprint = 'Crouched sprinting speed', speed_prone = 'Crawling speed',
    sprint_stamina_decay_duration = 'Seconds of sprinting on full stamina',
    jog_stamina_decay_duration = 'Seconds of jogging on full stamina',
    stamina_recover_time_stand = 'Seconds to recover stamina, standing',
    stamina_recover_time_crouch = 'Seconds to recover stamina, crouched',
    stamina_recover_time_prone = 'Seconds to recover stamina, prone',
    stamina_recover_delay = 'Seconds before stamina recovers',
    effect_armor_rating = 'Armor rating bonus (1 = one class)', effect_recoil_crouched = 'Recoil, crouched or prone',
    effect_extra_grenades = 'Extra grenades', effect_extra_stims = 'Extra stims',
    effect_stim_seconds = 'Stim lasts longer by (seconds)', effect_explosive_damage_taken = 'Explosive damage taken',
    effect_fire_damage_taken = 'Fire damage taken', effect_gas_damage_taken = 'Gas damage taken',
    effect_arc_damage_taken = 'Arc damage taken', effect_elemental_damage_taken = 'Fire, gas, acid, arc damage taken',
    effect_scan_seconds = 'Map marker scans every (seconds)', effect_detection_range = 'Range at which enemies notice',
    effect_melee_damage = 'Melee damage', effect_chest_damage_taken = 'Chest damage taken',
    effect_chest_bleed = 'Chest bleeding', effect_death_save = 'Chance to survive a lethal hit (1.5 = 50%)',
    effect_throw_range = 'Throwing range', effect_limb_health = 'Limb health', effect_noise = 'Noise made',
    effect_ergonomics_bonus = 'Ergonomics bonus',
    gun_flinch = 'Flinch when hit', gun_ammo_capacity = 'Ammo capacity', gun_primary_reload = 'Primary reload speed',
    gun_sidearm_reload = 'Sidearm reload speed', gun_sidearm_draw = 'Sidearm draw speed',
    gun_sidearm_recoil = 'Sidearm recoil',
    explosion_damage_multiplier = 'Explosion damage multiplier', constitution = 'Constitution',
    constitution_rate = 'Constitution change rate',
    inner_radius = 'Inner radius', outer_radius = 'Outer radius', stagger_radius = 'Stagger radius',
    shrapnel_count = 'Shrapnel count',
    duration = 'Duration (s)',
    from = 'Explodes like',
    to_main = 'Damage passed on to the vehicle', overflow_cap = 'Stops passing damage when destroyed',
}
local function menu_label(stat)
    local rest = stat
    if stat:sub(1, 5) == 'part_' then                       -- the heading names the part
        for _, ending in ipairs(MENU_PART_ENDS) do
            if stat:sub(-#ending) == ending then
                rest = ending:sub(2)
                break
            end
        end
    else
        rest = stat:match('^blast_(.+)$') or stat:match('^expiry_(.+)$') or stat   -- the heading says which explosion
    end
    -- a piece of shrapnel has the values of a hit of its own
    local piece = rest:match('^shrapnel_(.+)$')
    if piece and not MENU_LABEL[rest] then
        local label = menu_label(piece)
        return label ~= piece and (L('Shrapnel') .. ': ' .. label) or stat
    end
    local slot, what = rest:match('^status(%d)_(%a+)$')
    if slot then return L(what == 'type' and 'Status effect %s: type' or 'Status effect %s: strength'):format(slot) end
    local label = MENU_LABEL[rest]
    if label then return L(label) end
    if menu.lang == 'zh' then
        local id = stat:match('^effect_([0-9a-f]+)$')
        if id then return '未识别效果 ' .. id end
        id = stat:match('^gun_stat(%d+)$')
        if id then return '未识别武器属性 ' .. id end
    end
    return stat
end

-- -> heading, rank of the group a stat belongs to
local function menu_group(stat)
    if stat:sub(1, 5) == 'part_' then
        local name = stat:sub(6)
        for _, ending in ipairs(MENU_PART_ENDS) do
            if name:sub(-#ending) == ending then
                name = name:sub(1, -#ending - 1)
                break
            end
        end
        return 'PART: ' .. name, 900
    end
    local explosion = stat:match('^(blast)_') or stat:match('^(expiry)_')
    if explosion then
        local rest = stat:sub(#explosion + 2)
        local label = explosion == 'blast' and 'EXPLOSION' or 'EXPLOSION ON EXPIRY'
        if rest:find('^status%d_') then return label .. ': STATUS EFFECTS', explosion == 'blast' and 25 or 28 end
        return label, explosion == 'blast' and 24 or 27
    end
    if stat:find('^status%d_') then return 'STATUS EFFECTS', 15 end
    if stat == 'duration' then return 'STATUS', 5 end
    if stat:sub(1, 7) == 'effect_' then return 'EFFECTS', 700 end
    if stat:sub(1, 4) == 'gun_' then return 'WEAPONS IN HAND', 710 end
    if stat:sub(1, 4) == 'mod_' then return 'ON THE WEAPON IT IS FITTED TO', 720 end
    local known = MENU_GROUP_OF[stat]
    if known then return known[1], known[2] end
    return 'OTHER', 990
end

-- `blast_from` (the item explodes like another one) is not a number of a record but the name of an item:
-- in the value list it is a row of its own, and Left / Right walk through the items that explode.
function menu.takes_blast(item)
    return item.takeover ~= nil or (item.blasts ~= nil and item.blasts[1] ~= nil and item.blasts[1].kind == 'C')
end
function menu.donors()
    if menu.donor_list then return menu.donor_list end
    local list, seen = {}, {}
    -- the order of resolve_blast_from: a name that two categories have means the first one
    for _, category in ipairs({ 'weapon', 'throwable', 'stratagem_weapon', 'enemy_weapon', 'unknown_weapon' }) do
        for index = 0, #ITEMS do
            local it = ITEMS[index]
            if it and it.category == category and it.blasts and not seen[it.name:lower()] then
                seen[it.name:lower()] = true
                list[#list + 1] = it
            end
        end
    end
    table.sort(list, function(x, y) return (x.display or x.name):lower() < (y.display or y.name):lower() end)
    menu.donor_list = list
    return list
end
function menu.donor_shown(name)
    for _, it in ipairs(menu.donors()) do
        if it.name:lower() == tostring(name):lower() then return menu.name(it.display or it.name) end
    end
    return tostring(name)
end

-- The rows of the value list of an item: headings and values, and the values alone in that order.
function menu.base_rows(item)
    if item.base_rows then return item.base_rows, item.base_stats end
    local entries, first_seen, groups = {}, {}, 0
    for index, stat in ipairs(item.stat_order) do
        local label, rank = menu_group(stat)
        if not first_seen[label] then
            groups = groups + 1
            first_seen[label] = groups
        end
        entries[#entries + 1] = { stat = stat, label = label, rank = rank, first = first_seen[label], index = index }
    end
    if menu.takes_blast(item) then
        local label, rank = menu_group('blast_from')
        entries[#entries + 1] = { stat = 'blast_from', label = label, rank = rank, first = first_seen[label] or groups + 1,
                                  index = 0 }
    end
    table.sort(entries, function(x, y)
        if x.rank ~= y.rank then return x.rank < y.rank end
        if x.first ~= y.first then return x.first < y.first end
        return x.index < y.index
    end)
    local rows, stats, last = {}, {}, nil
    for _, entry in ipairs(entries) do
        if entry.label ~= last then
            last = entry.label
            rows[#rows + 1] = { heading = entry.label }
        end
        stats[#stats + 1] = entry.stat
        rows[#rows + 1] = { stat = entry.stat, n = #stats }
    end
    item.base_rows, item.base_stats = rows, stats
    return rows, stats
end

-- The value list as it is shown: every heading is a drop-down, closed or open. In a group each member is a
-- drop-down too (closed until it is opened), with its own headings inside.
-- -> rows { heading / stat, key, closed, level, parent, owner, n }, and what can be selected: stats[n] is
-- the name of a value, or false for a closed heading. An open heading is not selected, it is walked past.
function menu.is_closed(key, by_default)
    local set = menu.fold[key]
    if set == nil then return by_default end
    return set
end
local function menu_rows(item)
    if item.menu_rows and item.menu_version == menu.fold_version then return item.menu_rows, item.menu_stats end
    local rows, stats, owners, picks = {}, {}, {}, {}
    local function pick(row, stat, owner)
        stats[#stats + 1] = stat
        owners[#stats], picks[#stats], row.n = owner, row, #stats
    end
    local function values(member, under, level)
        local closed, heading_key = false, under
        for _, entry in ipairs(menu.base_rows(member)) do
            if entry.heading then
                heading_key = under .. '|' .. entry.heading
                closed = menu.is_closed(heading_key, not config.sections_open)
                local row = { heading = entry.heading, key = heading_key, closed = closed, level = level,
                              parent = level == 2 and under or nil }
                rows[#rows + 1] = row
                if closed then pick(row, false, member) end
            elseif not closed then
                local row = { stat = entry.stat, owner = member, parent = heading_key }
                rows[#rows + 1] = row
                pick(row, entry.stat, member)
            end
        end
    end
    if item.members then
        for _, member in ipairs(item.members) do
            local key = item.category .. '|' .. item.name .. '|' .. member.name
            local closed = menu.is_closed(key, true)
            local row = { heading = member.section, section = true, key = key, closed = closed, level = 1 }
            rows[#rows + 1] = row
            if closed then pick(row, false, member) else values(member, key, 2) end
        end
    else
        -- (one key for a heading whatever the item: DAMAGE opened on one weapon is open on the next)
        values(item, 'every item', 1)
    end
    item.menu_rows, item.menu_stats, item.menu_owners, item.menu_picks = rows, stats, owners, picks
    item.menu_version = menu.fold_version
    return rows, stats
end

-- Opens or closes the drop-down `key` of `item`, and puts the selection where one expects it: on the
-- heading that has just closed, on the first value of the one that has just opened.
function menu.toggle(item, key, close)
    local rows = menu_rows(item)
    local now_closed = close
    for _, row in ipairs(rows) do
        if row.key == key and row.heading then
            if now_closed == nil then now_closed = not row.closed end
        end
    end
    if now_closed == nil then return end
    menu.fold[key] = now_closed
    menu.fold_version = menu.fold_version + 1
    rows = menu_rows(item)
    local seen = false
    for _, row in ipairs(rows) do
        if row.key == key and row.heading then seen = true end
        if seen and row.n then
            menu.stat[item] = row.n
            return
        end
    end
end

-- the item a value of the list belongs to: the member of a group, or the item itself
function menu.owner(item, n)
    return item.menu_owners and item.menu_owners[n] or item
end

-- what the engine has to say about the selected value (the WARNING of its line), or nil
local function menu_warning(item, stat)
    for _, request in ipairs(config.requests) do
        if request.warning and request.stat == stat and request.category == item.category
            and request.item:lower() == item.name:lower() then
            return request.warning
        end
    end
    return nil
end

-- the value shown for a stat: the menu's own, else the game's. -> value, changed?
local function menu_value(item, stat)
    local expression = overrides[menu_key_of(item, stat)]
    if stat == 'blast_from' then return expression, expression ~= nil end       -- the name of an item, or nil
    return tonumber(expression) or item.stats[stat].field.stock, expression ~= nil
end

local function menu_change(item, stat, direction, big, now)
    if stat == 'blast_from' then
        -- 0 = its own explosion, then the items that explode, by name
        local list, key, at = menu.donors(), menu_key_of(item, stat), 0
        for n, it in ipairs(list) do
            if it.name:lower() == tostring(overrides[key]):lower() then at = n end
        end
        at = math.max(0, math.min(#list, at + direction * (big and 10 or 1)))
        overrides[key] = at > 0 and list[at].name or nil
        menu.dirty_at = now
        return
    end
    local entry, range = item.stats[stat], RANGES[stat]
    if not range then return end
    local whole = range.integer or entry.field.storage ~= 'f32'
    local size = math.abs(entry.field.stock)
    local step = whole and 1 or (size >= 100 and 10 or (size >= 10 and 1 or 0.1))
    if big then step = step * 10 end
    local value = menu_value(item, stat) + direction * step
    if not whole then value = math.floor(value * 1000 + 0.5) / 1000 end
    if value < range.min then value = range.min end
    if value > range.max then value = range.max end
    if same_value(entry.field.storage, value, entry.field.stock) then
        overrides[menu_key_of(item, stat)] = nil
    else
        overrides[menu_key_of(item, stat)] = whole and string.format('%.0f', value) or tostring(value)
    end
    menu.dirty_at = now
end

-- The list shown on the left: the items of the selected category, or, while a search is set, every
-- item of every category whose name (the game's or the internal one) contains it.
local function menu_current(lists)
    if menu.filter == '' then
        local category = MENU_CATEGORIES[menu.tab]
        return lists[category], category
    end
    if not menu.found or menu.found.filter ~= menu.filter then
        local found = { filter = menu.filter }
        for _, category in ipairs(MENU_CATEGORIES) do
            for _, item in ipairs(lists[category]) do
                -- an internal name has '_' where one types a space: "minigun b" finds minigun_backpack
                local internal = (item.name:lower():gsub('_', ' '))
                if (item.haystack and item.haystack:find(menu.filter, 1, true))
                    or (item.display or ''):lower():find(menu.filter, 1, true) or internal:find(menu.filter, 1, true)
                    or item.name:lower():find(menu.filter, 1, true) then
                    found[#found + 1] = item
                end
            end
        end
        menu.found, menu.item.search = found, 1
    end
    return menu.found, 'search'
end

-- a value typed in: rounded like the steps are, and kept inside the range
local function menu_set(item, stat, value, now)
    local entry, range = item.stats[stat], RANGES[stat]
    if not range then return end
    local whole = range.integer or entry.field.storage ~= 'f32'
    if whole then value = math.floor(value + 0.5) else value = math.floor(value * 1000 + 0.5) / 1000 end
    value = math.max(range.min, math.min(range.max, value))
    if same_value(entry.field.storage, value, entry.field.stock) then
        overrides[menu_key_of(item, stat)] = nil
    else
        overrides[menu_key_of(item, stat)] = whole and string.format('%.0f', value) or tostring(value)
    end
    menu.dirty_at = now
end

-- A heading of the value list in the chosen language; unidentified parts keep their hash.
local function menu_heading(heading)
    local part = heading:match('^PART: (.*)$')
    if part then return L('PART') .. ': ' .. menu.part_name(part) end
    return L(heading)
end

local function menu_say(text, now)
    menu.note, menu.note_until = text, (now or A.now()) + 4
end

-- ---- the game's own view of the keyboard and the mouse
-- While the menu is open the game must not act on a key or on the mouse.
-- What was tried, and what the game showed:
--   v1.1.4  the engine's level at which a button counts as down, raised above what a button can reach:
--           the calls went through and nothing changed. The game does not read its input through that.
--   v1.1.5  the process's raw input registration taken away: the log showed that the game registers raw
--           input for the mouse only (usage 1/2). So that is the mouse, and the keys come another way.
--   v1.1.6  the keys come to the game's window as ordinary key messages, which Windows sends to the
--           window that has the keyboard focus. While the menu is open the focus is on a window of our
--           own (no size, inside the game's window); when it closes the game's window has it back.
-- The menu asks Windows for the state of a key, which depends on neither.
--   v1.1.7  the game's window belongs to another thread than the one this runs on (seen in the log of
--           v1.1.6); the focus is moved from here all the same, see menu.block_keys.
--   v1.1.17 the focus is not touched any more. Seen in game with v1.1.16: giving it to the helper window
--           made the game stop answering in that very call (the game's window is "not active" then, and
--           its thread and this one wait for each other). Every way of moving the focus has now either
--           let keys through or stopped the game. The keys are instead dropped where the game's window
--           thread takes them off its queue, by a message filter that runs on that thread (a.hook_code).
--           Nothing about focus, activation or Alt+Tab changes. Decided with the user, who was told
--           that it is machine code put into the game's process and that the anti-cheat's view of it is
--           not known.
--   v1.1.15 the focus goes to the helper window Windows itself made for the game's window thread (class
--           "IME"), enabled for as long. Seen in game with v1.1.14 (focus on no window): no hang on
--           Alt+Tab any more, but a sound on every key and Backspace still opened the game's menu:
--           Windows sends the keys to the active window as "system key" messages then. With the focus on
--           the helper the game's window sees neither kind (tried on a test window, build/an_focus6.py),
--           and the helper is the window thread's own, so nothing waits for this thread.
--   v1.1.14 no window of ours any more. Seen in game (v1.1.13): Alt+Tab with the menu open, and the game
--           stopped answering; watch.txt was last written with the game still in front. When the game is
--           switched away from, its window thread tells the window that has the focus and waits for the
--           answer; that window was ours, on this thread, and this thread was not running then. Now the
--           focus is set to no window at all: the game's window gets no key messages (Windows sends the
--           keys to the active window as "system key" messages instead; whether the game reads those is
--           the open question), and nothing of ours takes part in what Windows does on a switch.
--   v1.1.13 users of v1.1.12 reported the game stopping to answer: when one switches to another window
--           with the menu open, when a value is changed. On the tester's computer Windows recorded the
--           game as "stopped interacting" six times, all after v1.1.7. Not reproduced on a test window
--           (build/an_focus3.py). A window of ours that has the focus makes the game's window thread
--           send messages to this thread and wait for them, and this thread sends to that one when it
--           moves the focus: two threads that can wait for each other. So the focus is now held with
--           care, see menu.block_watch, and watch.txt says once a second what the state is.
-- settings.txt carries a mark while the first try of a session runs: when the game closed during it,
-- the next start leaves the blocking off.
function menu.block_mouse(on)
    if on then
        local ok, devices = pcall(A.raw_devices)
        if not ok or type(devices) ~= 'table' then
            log('menu: the raw input registration cannot be read: ' .. tostring(devices))
            return false
        end
        local mine, seen = {}, {}
        for _, d in ipairs(devices) do
            seen[#seen + 1] = string.format('%d/%d flags %X window %s', d.page, d.usage, d.flags,
                                            d.window ~= 0 and hex(d.window) or '-')
            -- usage page 1: generic desktop; usage 2: mouse, 6: keyboard
            if d.page == 1 and (d.usage == 2 or d.usage == 6) then mine[#mine + 1] = d end
        end
        if not menu.raw_logged then
            menu.raw_logged = true
            log('menu: raw input registered by the game: ' .. (#seen > 0 and table.concat(seen, ', ') or 'none'))
        end
        if #mine == 0 then return false end
        menu_step('RegisterRawInputDevices (remove keyboard and mouse)')
        local removal = {}
        for _, d in ipairs(mine) do removal[#removal + 1] = { page = d.page, usage = d.usage, flags = 1, window = 0 } end
        if not A.raw_register(removal) then
            log('menu: the raw input registration could not be taken away')
            return false
        end
        menu.raw_saved = mine
        return true
    elseif menu.raw_saved then
        if not A.raw_register(menu.raw_saved) then log('menu: FAILED: the raw input registration could not be put back') end
        menu.raw_saved = nil
    end
end
function menu.block_keys(on)
    if on then
        local window, same_thread, thread = A.game_window()
        if not window then return false end
        if not menu.window_logged then
            menu.window_logged = true
            log('menu: the game window ' .. hex(window) .. ' belongs to ' .. (same_thread and 'this thread' or 'another thread'))
        end
        menu_step('SetWindowsHookExA (a message filter on the game window thread)')
        local ok, where = A.hook_install(thread)
        if not ok then
            log('menu: the message filter could not be installed: ' .. tostring(where))
            return false
        end
        if type(where) == 'number' then log('menu: message filter installed, code at ' .. hex(where)) end
        if not A.hook_on(true) then return false end
        menu.keys_blocked = { window = window, thread = thread, how = 'message filter' }
        return true
    elseif menu.keys_blocked then
        menu.keys_blocked = nil
        A.hook_on(false)
    end
end
-- Once a second while the keys are blocked: what a later look at a game that stopped answering needs.
function menu.block_watch(now)
    local b = menu.keys_blocked
    if not b or (b.noted and now - b.noted < 1) then return end
    b.noted = now
    write_file('watch.txt', string.format('frame %d\r\nfilter on\r\nin front %s\r\nwindow answers %s\r\nmode %s\r\n',
        state.frame, tostring(A.game_in_front()), tostring(not A.window_hung(b.window)), tostring(menu.mode)))
end
local function menu_block_game(on)
    if on and not menu.blocked then
        local mouse = menu.block_mouse(true)
        local keys = menu.block_keys(true)
        if not mouse and not keys then
            menu.block_missing = true
            return false
        end
        menu.blocked = true
        log('menu: game input blocked (keyboard: ' .. (keys and menu.keys_blocked.how or 'no') .. ', mouse: '
            .. (mouse and 'raw input' or 'no') .. ')')
    elseif not on and menu.blocked then
        menu.blocked = false
        menu.block_keys(false)
        menu.block_mouse(false)
        log('menu: game input given back')
    end
    return true
end

local function menu_start()
    local S = rawget(_G, 'stingray')
    if type(S) ~= 'table' or type(S.Application) ~= 'table' or type(S.World) ~= 'table' or type(S.Gui) ~= 'table' then
        return nil, 'the engine has no Gui here'
    end
    menu_step('Application.main_world()')
    local ok, world = pcall(S.Application.main_world)
    if not ok or world == nil then return nil, 'no world to draw in' end
    menu_step('World.create_screen_gui(world, "immediate")')
    local made, gui = pcall(S.World.create_screen_gui, world, 'immediate')
    if not made or gui == nil then return nil, 'the screen gui could not be created: ' .. tostring(gui) end
    menu.S, menu.world, menu.gui = S, world, gui
    if not menu.font then
        menu_step('Gui.text (font test)')
        for _, font in ipairs(MENU_FONTS) do
            if not menu.font and pcall(function()
                S.Gui.text(gui, ' ', font, 16, font, S.Vector2(0, 0), S.Color(0, 0, 0, 0))
            end) then menu.font = font end
        end
    end
    if not menu.font then return nil, 'no font could be used' end
    -- Fonts for Chinese: only what the engine says it has loaded. Asked once.
    if not menu.zh_asked then
        menu.zh_asked = true
        if type(S.Application.can_get) == 'function' then
            menu_step('Application.can_get(type, name) for the Chinese font')
            for _, c in ipairs(MENU_FONTS_ZH) do
                local asked, there = pcall(S.Application.can_get, c[1], c[2])
                local asked_m, there_m = pcall(S.Application.can_get, 'material', c[3])
                local usable = asked and there and asked_m and there_m
                log('menu: font ' .. c[2] .. ' (' .. c[1] .. '): ' .. (usable and 'there' or 'not there'))
                if usable then menu.zh_fonts[#menu.zh_fonts + 1] = { font = c[2], material = c[3] } end
            end
        else
            log('menu: the engine cannot be asked for fonts: no Chinese')
        end
        menu.zh_font = menu.zh_fonts[1]
        if menu.lang == 'zh' and (not menu.zh_font or menu.zh_failed) then menu.lang, menu.lang_saved = 'en', 'en' end
    end
    -- Draw order. In game (v0.15.1) the panel and the selection bars covered the text: the Gui does not
    -- draw in call order. A Vector3 position carries a layer in z; whether this build takes one is
    -- tried once, and without layers nothing is drawn that could cover text.
    if menu.layers == nil then
        menu_step('Gui.rect / Gui.text with a Vector3 position (layer)')
        menu.layers = pcall(function()
            S.Gui.rect(gui, S.Vector3(0, 0, 900), S.Vector2(1, 1), S.Color(0, 0, 0, 0))
            S.Gui.text(gui, ' ', menu.font, 16, menu.font, S.Vector3(0, 0, 902), S.Color(0, 0, 0, 0))
        end)
        log('menu: layers ' .. (menu.layers and 'available' or 'not available: drawn without panel and bars'))
    end
    if menu.block then
        if not menu.block_tried then
            menu.block_trying = true
            pcall(menu_settings_save)
        end
        menu_block_game(true)
        if not menu.block_tried then
            menu.block_tried, menu.block_trying = true, nil
            pcall(menu_settings_save)
        end
    end
    return true
end

local function menu_close(now)
    menu.open, menu.state, menu.width = false, 'closed', nil
    menu.mode, menu.box, menu.capture, menu.ask = 'list', nil, nil, nil
    if menu.zh_trying then
        -- closed before the try was over: frames were drawn and the game is still here
        menu.zh_trying = nil
        if (menu.zh_frames or 0) >= 2 then menu.lang_saved = 'zh' else menu.lang = 'en' end
        pcall(menu_settings_save)
    end
    pcall(menu_block_game, false)
    if menu.S and menu.gui then
        menu_step('World.destroy_gui(world, gui)')
        pcall(menu.S.World.destroy_gui, menu.world, menu.gui)
    end
    menu.gui, menu.world = nil, nil
    if menu.dirty_at then
        menu.dirty_at = nil
        request_reload()
    end
    pcall(menu_save)
end

-- ---- typing into a box
-- kind: 'search' (anything), 'value' (a number), 'name' (a file name)
local function menu_box_open(kind, text, done)
    menu.mode = 'text'
    menu.box = { kind = kind, text = text or '', done = done }
    -- (v1.1.10 in game: opening the value box made the game stop answering, and nothing said where)
    if not menu_trail['box ' .. kind] then
        log('menu: the ' .. kind .. ' box opens')
        flush_log()
    end
    -- keys held right now belong to what was done before the box opened
    for _, typed in ipairs(MENU_TYPED) do
        if A.key_down(KEY_VK[typed[1]]) then menu.keys[typed[1]] = { since = 1e18, last = 1e18 } end
    end
end
local function menu_box_input(now)
    local box = menu.box
    local shift = A.key_down(KEY_VK.SHIFT)
    for _, typed in ipairs(MENU_TYPED) do
        if menu_key_pressed(typed[1], now) then
            local char = shift and typed[3] or typed[2]
            local fits = true
            if box.kind == 'value' then
                fits = char:find('^[%d%.%-]$') ~= nil and #box.text < 12
            elseif box.kind == 'name' then
                fits = char:find('^[%w _%-]$') ~= nil and #box.text < 24
            else
                char = char:lower()
                fits = #box.text < 24
            end
            if fits then box.text = box.text .. char end
        end
    end
    if menu_key_pressed('BACKSPACE', now) then box.text = box.text:sub(1, -2) end
    if box.kind == 'search' then menu.filter = box.text end
    if menu_act('accept', now, true) then
        menu.mode, menu.box = 'list', nil
        if box.done then box.done(box.text, now) end
    elseif menu_act('back', now, true) then
        menu.mode, menu.box = 'list', nil
        if box.kind == 'search' then menu.filter = '' end
    end
end

-- ---- the pages
local function menu_items_input(now, lists)
    local list, category = menu_current(lists)
    local selected = math.min(menu.item[category] or 1, math.max(#list, 1))
    local item = list[selected]
    local big = A.key_down(KEY_VK[menu_bound('fast')] or 0)
    local function move(by)
        if menu.focus == 'items' then
            menu.item[category] = math.max(1, math.min(#list, selected + by))
        elseif item then
            local at = menu.stat[item] or 1
            local _rows, stats = menu_rows(item)
            menu.stat[item] = math.max(1, math.min(#stats, at + by))
        end
    end
    if menu_act('search', now, true) then
        menu.focus = 'items'
        menu_box_open('search', menu.filter)
        return
    end
    if menu_act('column', now) then menu.focus = menu.focus == 'items' and 'stats' or 'items' end
    if menu_act('up', now) then move(-1) end
    if menu_act('down', now) then move(1) end
    if menu_act('page_up', now) then move(-10) end
    if menu_act('page_down', now) then move(10) end
    local side = (menu_act('right', now) and 1 or 0) - (menu_act('left', now) and 1 or 0)
    if side ~= 0 then
        if menu.focus == 'items' then
            if menu.filter == '' then menu.tab = (menu.tab - 1 + side) % #MENU_CATEGORIES + 1 end
        elseif item then
            local _rows, stats = menu_rows(item)
            local at = math.min(menu.stat[item] or 1, #stats)
            if stats[at] then
                menu_change(menu.owner(item, at), stats[at], side, big, now)
            elseif stats[at] == false and side > 0 then
                menu.toggle(item, item.menu_picks[at].key, false)       -- a closed heading: Right opens it
            end
        end
    end
    if menu_act('back', now, true) then
        -- among the values: close the drop-down one is in (a value's heading; a closed heading's group
        -- member). Where there is nothing to close, and in the item list, it clears the search.
        local folded = false
        if menu.focus == 'stats' and item then
            local _rows, stats = menu_rows(item)
            local row = item.menu_picks[math.min(menu.stat[item] or 1, #stats)]
            if row and row.parent then
                menu.toggle(item, row.parent, true)
                folded = true
            elseif row and row.stat and not row.parent then
                folded = false
            end
        end
        if not folded and menu.filter ~= '' then menu.filter = '' end
    end
    if menu.focus == 'stats' and item then
        local _rows, stats = menu_rows(item)
        local chosen = math.min(menu.stat[item] or 1, #stats)
        local stat, owner = stats[chosen], menu.owner(item, chosen)
        if stat == false and menu_act('accept', now, true) then
            menu.toggle(item, item.menu_picks[chosen].key, false)       -- a closed heading: the select key opens it
            return
        end
        if stat and menu_act('reset', now, true) then
            overrides[menu_key_of(owner, stat)] = nil
            menu.dirty_at = now
        end
        if stat and stat ~= 'blast_from' and menu_act('accept', now, true) then
            menu_box_open('value', '', function(text, at)
                local value = tonumber(text)
                if value then menu_set(owner, stat, value, at) end
            end)
        end
    elseif menu.focus == 'items' and menu_act('accept', now, true) then
        -- seen in game (v1.1.1): testers pressed the select key to get into the search and landed in the
        -- value list. In the item list it opens the search box; the lists are switched with their own key.
        menu_box_open('search', menu.filter)
    end
end

local function menu_presets_input(now)
    local rows = #menu.presets + 2
    menu.preset_row = math.max(1, math.min(rows, menu.preset_row))
    if menu_act('up', now) then menu.preset_row = math.max(1, menu.preset_row - 1) end
    if menu_act('down', now) then menu.preset_row = math.min(rows, menu.preset_row + 1) end
    local name = menu.presets[menu.preset_row]
    if name then
        local side = (menu_act('right', now) and 1 or 0) - (menu_act('left', now) and 1 or 0)
        menu.preset_action = (menu.preset_action - 1 + side) % #MENU_PRESET_ACTIONS + 1
    end
    if not menu_act('accept', now, true) then return end
    local function create(values_of)
        menu_box_open('name', '', function(text, at)
            local new = preset_clean(text)
            if not new then return menu_say(L('A name needs a letter or a digit'), at) end
            if preset_known(new) then return menu_say(L('That name is taken'), at) end
            pcall(menu_save)                                   -- what was open is kept as it is
            local values = values_of()
            if not write_file(preset_file(new), preset_text(values)) then
                return menu_say(L('The file could not be written'), at)
            end
            preset_use(new, values)
            menu_say(L('Preset "%s" is active'):format(new), at)
        end)
    end
    if not name then
        if menu.preset_row == #menu.presets + 1 then
            create(function() return {} end)
        else
            create(function()
                local copy = {}
                for key, value in pairs(overrides) do copy[key] = value end
                return copy
            end)
        end
        return
    end
    local action = MENU_PRESET_ACTIONS[menu.preset_action]
    local dir = ensure_out_dir()
    if action == 'Activate' then
        if name ~= preset_name then
            pcall(menu_save)
            preset_use(name, preset_parse(read_file(preset_file(name))))
        end
        menu_say(L('Preset "%s" is active'):format(name), now)
    elseif action == 'Rename' or action == 'Duplicate' then
        menu_box_open('name', action == 'Rename' and name or '', function(text, at)
            local new = preset_clean(text)
            if not new then return menu_say(L('A name needs a letter or a digit'), at) end
            if preset_known(new) and new:lower() ~= name:lower() then return menu_say(L('That name is taken'), at) end
            if name == preset_name then pcall(menu_save) end
            local content = read_file(preset_file(name))
            if not content or not write_file(preset_file(new), content) then
                return menu_say(L('The file could not be written'), at)
            end
            if action == 'Rename' and new ~= name then
                if dir and new:lower() ~= name:lower() then os.remove(dir .. '\\' .. preset_file(name)) end
                if name == preset_name then preset_name = new end
            end
            preset_scan()
            pcall(menu_settings_save)
        end)
    elseif action == 'Delete' then
        menu.mode, menu.ask = 'confirm', { name = name }
    end
end

local function menu_confirm_input(now)
    local name = menu.ask.name
    if menu_act('accept', now, true) then
        menu.mode, menu.ask = 'list', nil
        local dir = ensure_out_dir()
        if dir then os.remove(dir .. '\\' .. preset_file(name)) end
        preset_scan()
        if name == preset_name then
            -- the active one is gone: the next one takes over, or an empty Default
            local next_name = menu.presets[1] or 'Default'
            preset_name = nil
            preset_use(next_name, menu.presets[1] and preset_parse(read_file(preset_file(next_name))) or {})
        end
        menu.preset_row = 1
    elseif menu_act('back', now, true) then
        menu.mode, menu.ask = 'list', nil
    end
end

-- the rows of the Keys page: the actions, then the two switches
local function menu_keys_input(now)
    local rows = #MENU_ACTIONS + 2
    if menu_act('up', now) then menu.key_row = math.max(1, menu.key_row - 1) end
    if menu_act('down', now) then menu.key_row = math.min(rows, menu.key_row + 1) end
    if not menu_act('accept', now, true) then return end
    local action = MENU_ACTIONS[menu.key_row]
    if action then
        -- keys held right now are not the answer
        local held = {}
        for _, key in ipairs(KEY_ORDER) do
            if A.key_down(KEY_VK[key]) then held[key] = true end
        end
        menu.mode, menu.capture = 'capture', { action = action[1], label = action[3], held = held }
    elseif menu.key_row == #MENU_ACTIONS + 1 then
        menu.block = not menu.block
        local worked = menu_block_game(menu.block)
        if menu.block and not worked then menu.block = false end
        -- written down only once the engine has taken it without closing the game
        menu.block_saved = menu.block
        pcall(menu_settings_save)
    else
        menu.bind = {}
        pcall(menu_settings_save)
    end
end
local function menu_capture_input(now)
    local capture = menu.capture
    for _, key in ipairs(KEY_ORDER) do
        local down = A.key_down(KEY_VK[key])
        if not down then
            capture.held[key] = nil
        elseif not capture.held[key] then
            menu.mode, menu.capture = 'list', nil
            menu.keys[key] = { since = 1e18, last = 1e18 }          -- this press is spent
            if key ~= menu_bound('back') or capture.action == 'back' then
                menu.bind[capture.action] = key
                pcall(menu_settings_save)
                local clash = menu_key_clash()
                if clash then menu_say(L('Two actions share the key %s'):format(clash), now) end
            end
            return
        end
    end
end

local function menu_language_input(now)
    local rows = 2
    if menu_act('up', now) then menu.lang_row = math.max(1, menu.lang_row - 1) end
    if menu_act('down', now) then menu.lang_row = math.min(rows, menu.lang_row + 1) end
    if not menu_act('accept', now, true) then return end
    if menu.lang_row == 1 then
        menu.lang, menu.lang_saved, menu.zh_trying = 'en', 'en', nil
        pcall(menu_settings_save)
    elseif menu.zh_failed then
        menu_say(L('Chinese is switched off: the game stopped when it was drawn'), now)
    elseif not menu.zh_font then
        menu_say(L('no font of the game can draw Chinese'), now)
    elseif menu.lang ~= 'zh' then
        -- Seen in game (v1.1.7): drawing with a font the engine has can still make the game stop
        -- answering. So the file says "being tried" before the first frame in Chinese, and "Chinese"
        -- only after a second's worth of frames; a start that finds "being tried" never tries again.
        menu.lang, menu.zh_frames = 'zh', 0
        if menu.lang_saved ~= 'zh' then
            menu.zh_trying = true
            menu_settings_save()
            flush_log()
        end
    end
end

local function menu_input(now)
    local lists = menu_lists()
    if not lists or not A.game_in_front() then return end
    menu.accept_now, menu.click_accept = menu.click_accept, nil
    if menu.mode == 'text' then
        menu_box_input(now)
    elseif menu.mode == 'capture' then
        menu_capture_input(now)
    elseif menu.mode == 'confirm' then
        menu_confirm_input(now)
    else
        local turn = (menu_act('next_page', now, true) and 1 or 0) - (menu_act('prev_page', now, true) and 1 or 0)
        if turn ~= 0 then
            menu.page = (menu.page - 1 + turn) % #MENU_PAGES + 1
        elseif menu.page == 1 then
            menu_items_input(now, lists)
        elseif menu.page == 2 then
            menu_presets_input(now)
        elseif menu.page == 3 then
            menu_keys_input(now)
        else
            menu_language_input(now)
        end
    end
    -- a change is handed to the engine when the keys have been quiet for a moment
    if menu.dirty_at and now - menu.dirty_at > 0.3 then
        menu.dirty_at = nil
        request_reload()
        pcall(menu_save)
        menu.saved_at = now
    end
end

local function menu_draw(now)
    local S, gui = menu.S, menu.gui
    if not menu.width then
        menu.width, menu.height = 1920, 1080
        menu_step('Application.back_buffer_size()')
        local ok, w, h = pcall(S.Application.back_buffer_size)
        if ok and type(w) == 'number' and type(h) == 'number' and w >= 640 and h >= 360 then
            menu.width, menu.height = w, h
        end
        log('menu: screen ' .. tostring(menu.width) .. ' x ' .. tostring(menu.height))
    end
    local width, height = menu.width, menu.height
    local scale = height / 1080
    menu_step('Gui.rect / Gui.text (first frame)')
    local PANEL_W, PANEL_H = 1180, 726
    local left, bottom = (width - PANEL_W * scale) / 2, (height - PANEL_H * scale) / 2
    -- panel coordinates: x from the left edge, y from the TOP edge of the panel (the Gui's origin is bottom left)
    local layers = menu.layers
    local font, material = menu.font, menu.font
    if menu.lang == 'zh' and menu.zh_font then
        font, material = menu.zh_font.font, menu.zh_font.material
        menu_step('Gui.text with the font ' .. font .. ' and the material ' .. material)
    end
    -- layer 900: the panel, 901: bars on it, 902: text
    local function rect(x, y, w_, h_, a, r, g, b, layer)
        if not layers then return end
        S.Gui.rect(gui, S.Vector3(left + x * scale, bottom + (PANEL_H - y - h_) * scale, layer or 901),
                   S.Vector2(w_ * scale, h_ * scale), S.Color(a, r, g, b))
    end
    local function text(str, x, y, size, a, r, g, b)
        local px, py = left + x * scale, bottom + (PANEL_H - y - size) * scale
        S.Gui.text(gui, str, font, size * scale, material,
                   layers and S.Vector3(px, py, 902) or S.Vector2(px, py), S.Color(a, r, g, b))
    end
    local function gray(str, x, y, size) text(str, x, y, size or 14, 255, 210, 210, 210) end
    local function yellow(str, x, y, size) text(str, x, y, size or 14, 255, 255, 214, 0) end
    -- a row of a list: a bar when it is the selected one, dark text on a bright bar
    -- The mouse. The game hides its pointer, so the menu draws one. Where it is comes from Windows, in
    -- the window's own pixels; the panel is laid out in the back buffer's, x from its left edge and y
    -- from its top edge. It only counts once it has moved: a pointer that never moves is not in use.
    local mouse, hot = nil, {}
    local window = A.game_window()
    if window then
        local ok, cx, cy, cw, ch = pcall(A.mouse, window)
        if ok and cx and cw and cw > 0 and ch > 0 then
            mouse = { x = (cx * width / cw - left) / scale,
                      y = (cy * height / ch - (height - bottom - PANEL_H * scale)) / scale }
            if menu.mouse_at and (menu.mouse_at.x ~= cx or menu.mouse_at.y ~= cy) then menu.mouse_used = true end
            menu.mouse_at = { x = cx, y = cy }
        end
    end
    -- an area that does something when it is clicked; where two overlap, the one made later counts
    local function area(x, y, w_, h_, action) hot[#hot + 1] = { x, y, w_, h_, action } end
    -- on the pages that are plain lists: a click selects a row, a click on the selected row confirms it
    local function pick(current, n, set)
        return function()
            if current == n then menu.click_accept = true else set(n) end
        end
    end
    local function row(label, x, y, w_, here, focused, cells, on_click)
        if on_click then area(x - 8, y, w_, 24, on_click) end
        if here then rect(x - 8, y, w_, 24, 255, focused and 255 or 70, focused and 214 or 70, focused and 0 or 60) end
        label = menu_clip(label, cells or 60)
        if not layers and here then label = '> ' .. label end
        if focused and layers then text(label, x, y + 3, 17, 255, 0, 0, 0)
        elseif here and not layers then text(label, x, y + 3, 17, 255, 255, 214, 0)
        else text(label, x, y + 3, 17, 255, 255, 255, 255) end
    end
    local function key(action) return menu.key_name(menu_bound(action)) end
    rect(0, 0, PANEL_W, PANEL_H, 245, 8, 10, 14, 900)
    rect(0, 0, PANEL_W, 4, 255, 255, 214, 0)
    text(L('BALANCE YOUR OWN GAME') .. '   v' .. MOD.version, 20, 16, 24, 255, 255, 214, 0)
    gray(L('Preset') .. ': ' .. tostring(preset_name or ''), 860, 22, 16)
    -- pages
    local x = 20
    for n, page in ipairs(MENU_PAGES) do
        local label = L(page)
        local w_ = 22 + menu_cells(label) * 10
        area(x, 50, w_, 26, function() menu.page = n end)
        if n == menu.page then
            rect(x, 50, w_, 26, 255, 255, 214, 0)
            if layers then text(label, x + 11, 54, 17, 255, 0, 0, 0) else yellow(label, x + 11, 54, 17) end
        else
            text(label, x + 11, 54, 17, 255, 255, 255, 255)
        end
        x = x + w_ + 6
    end
    gray(key('prev_page') .. ' / ' .. key('next_page') .. '  ' .. L('page'), x + 14, 56, 14)
    rect(16, 80, PANEL_W - 32, 1, 255, 120, 100, 0)

    local hints = {}
    local function hint(keys, what) hints[#hints + 1] = keys .. ' ' .. L(what) end
    local TOP = 150
    local lists = menu_lists()
    if not lists then
        text(L('reading the built-in data ...'), 20, TOP, 18, 255, 220, 220, 220)
    elseif menu.page == 1 then
        -- categories
        x = 20
        local searching = menu.filter ~= '' or (menu.box and menu.box.kind == 'search')
        for n, category in ipairs(MENU_CATEGORIES) do
            local active = n == menu.tab and not searching
            local label = L(MENU_CATEGORY_NAME[category]) .. (active and (' ' .. #lists[category]) or '')
            local w_ = 10 + menu_cells(label) * 9                -- (thirteen of them have to fit)
            area(x, 88, w_, 24, function() menu.tab, menu.filter, menu.focus = n, '', 'items' end)
            if active then
                rect(x, 88, w_, 24, 255, 70, 70, 60)
                yellow(label, x + 5, 92, 16)
            else
                local c = searching and 120 or 255
                text(label, x + 5, 92, 16, 255, c, c, c)
            end
            x = x + w_ + 4
        end
        local list, category = menu_current(lists)
        local selected = math.min(menu.item[category] or 1, math.max(#list, 1))
        local item = list[selected]
        -- items
        local first = math.max(1, math.min(selected - 8, #list - MENU_ROWS + 1))
        for at = 0, MENU_ROWS - 1 do
            local entry = list[first + at]
            if entry then
                local here = first + at == selected
                local label = menu.name(entry.display or entry.name)
                if category == 'search' then
                    label = menu_clip(label, 24) .. '  [' .. L(MENU_CATEGORY_TAG[entry.category]) .. ']'
                end
                row(label, 24, TOP + at * 26, 400, here, here and menu.focus == 'items' and menu.mode == 'list',
                    category == 'search' and 42 or 38, function()
                        menu.item[category], menu.focus = first + at, 'items'
                    end)
            end
        end
        local under = TOP + MENU_ROWS * 26 + 6
        gray(string.format('%d %s %d', #list > 0 and selected or 0, L('of'), #list), 330, under)
        -- the search box, above the item list
        local box_y = TOP - 26
        area(16, box_y - 3, 400, 22, function()
            menu.focus = 'items'
            menu_box_open('search', menu.filter)
        end)
        if menu.box and menu.box.kind == 'search' then
            rect(16, box_y - 3, 400, 22, 255, 255, 214, 0)
            if layers then text(L('search') .. ': ' .. menu.box.text .. '_', 24, box_y, 16, 255, 0, 0, 0)
            else yellow(L('search') .. ': ' .. menu.box.text .. '_', 24, box_y, 16) end
        elseif menu.filter ~= '' then
            rect(16, box_y - 3, 400, 22, 255, 70, 70, 60)
            yellow(L('search') .. ': ' .. menu.filter, 24, box_y, 16)
        else
            rect(16, box_y - 3, 400, 22, 255, 40, 42, 46)
            local keys = menu.focus == 'items' and (key('accept') .. ' / ' .. key('search')) or key('search')
            text(L('press %s to search'):format(keys), 24, box_y + 1, 14, 255, 170, 170, 170)
        end
        -- values of the selected item
        if item then
            gray(item.members and (#item.members .. ' ' .. L('items, one section each'))
                 or (item.display and (item.name .. '   (' .. L('name in config.txt') .. ')') or ''), 444, TOP - 22, 15)
            gray(L('value'), 800, TOP - 22, 15)
            gray(L('game'), 980, TOP - 22, 15)
            local rows, stats = menu_rows(item)
            local at = math.min(menu.stat[item] or 1, #stats)
            local at_row = 1
            for index, entry in ipairs(rows) do
                if entry.n == at then at_row = index end
            end
            -- the window of rows: the selected value near the middle, its heading in view when it is close
            local top = math.max(1, math.min(at_row - 8, #rows - MENU_ROWS + 1))
            for n = 0, MENU_ROWS - 1 do
                local entry = rows[top + n]
                local stat = entry and entry.stat
                local y = TOP + n * 26
                if entry and entry.heading then
                    -- a drop-down: [+] closed, [-] open; a click opens or closes it
                    local label = (entry.closed and '[+] ' or '[-] ')
                        .. (entry.section and menu.name(entry.heading):upper() or menu_heading(entry.heading))
                    local inset = (item.members and entry.level == 2) and 20 or 0
                    local toggle = function()
                        menu.focus = 'stats'
                        menu.toggle(item, entry.key)
                    end
                    if entry.n then
                        local here = entry.n == at
                        row(menu_clip(label, 76), 444 + inset, y, 728 - inset, here,
                            here and menu.focus == 'stats' and menu.mode ~= 'capture', 76, toggle)
                    else
                        area(436, y, 728, 26, toggle)
                        rect(436, y + 21, 728, 1, 255, 120, 100, 0)
                        yellow(menu_clip(label, 76), 444 + inset, y + 5, 14)
                    end
                end
                if stat then
                    local owner = entry.owner or item
                    local value, changed = menu_value(owner, stat)
                    -- (`blast_from` has no field: its value is the name of an item)
                    local field = owner.stats[stat] and owner.stats[stat].field
                    local here = entry.n == at
                    local focused = here and menu.focus == 'stats' and menu.mode ~= 'capture'
                    row(menu_label(stat), 460, y, 728 - 16, here, focused, 34, function()
                        -- on the name: select the value; on the number: type it
                        menu.stat[item], menu.focus = entry.n, 'stats'
                        if mouse and mouse.x >= 790 and stat ~= 'blast_from' then
                            menu_box_open('value', '', function(typed, at_time)
                                local number = tonumber(typed)
                                if number then menu_set(owner, stat, number, at_time) end
                            end)
                        end
                    end)
                    local dark = focused and layers
                    local c = dark and 0 or 255
                    local shown = field and show(value, field.storage) or (value and menu.donor_shown(value) or L('its own'))
                    if stat:find('status%d_type$') and MENU_STATUS[value] then shown = shown .. '  ' .. menu.name(MENU_STATUS[value]) end
                    if here and menu.box and menu.box.kind == 'value' then
                        -- never a text that is nothing but "_": the one thing the frame did in which the
                        -- game stopped answering (v1.1.10) and no other frame does
                        text('= ' .. menu.box.text .. '_', 800, y + 3, 17, 255, c, c, c)
                    elseif changed and not dark then
                        text(menu_clip(shown, field and 17 or 34), 800, y + 3, 17, 255, 255, 214, 0)
                    else
                        text(menu_clip(shown, field and 17 or 34), 800, y + 3, 17, 255, c, c, c)
                    end
                    local stock = field and show(field.stock, field.storage) or ''
                    if owner.hints and owner.hints[stat] then stock = stock .. ' (' .. (menu.lang == 'zh' and owner.hints[stat]:gsub('^wiki ', '百科 ') or owner.hints[stat]) .. ')' end
                    if field and stat:find('status%d_type$') and MENU_STATUS[field.stock] then
                        stock = stock .. '  ' .. menu.name(MENU_STATUS[field.stock])
                    end
                    if dark then text(menu_clip(stock, 22), 980, y + 3, 17, 255, 0, 0, 0)
                    else gray(menu_clip(stock, 22), 980, y + 3, 17) end
                end
            end
            gray(string.format('%d %s %d', at, L('of'), #stats), 444, under)
            local owner = menu.owner(item, at)
            if stats[at] then
                if menu.lang == 'zh' then
                    gray(menu_clip(menu_label(stats[at]), 84), 560, under)
                    gray(menu_clip((item.members and ('[' .. owner.name .. '] ') or '') .. stats[at], 80)
                         .. ' (' .. L('name in config.txt') .. ')', 560, under + 14, 11)
                else
                gray(menu_clip((item.members and ('[' .. owner.name .. '] ') or '') .. stats[at], 60) .. '   ('
                     .. L('name in config.txt') .. ')', 560, under)
                end
            end
            local warning = stats[at] and menu_warning(owner, stats[at])
            if item.category == 'status' then
                warning = warning or L('A status effect has one length: it is the same for every weapon and enemy that applies it')
            end
            if warning and not menu.note then yellow('! ' .. menu_clip(menu.message(warning), 150), 20, PANEL_H - 76) end
        end
        if menu.mode == 'text' then
            hint(key('accept'), 'confirm'); hint(key('back'), 'cancel'); hint(menu.key_name('BACKSPACE'), 'delete a letter')
        else
            hint(key('up') .. '/' .. key('down'), 'move'); hint(key('column'), 'lists')
            hint(key('left') .. '/' .. key('right'), 'change'); hint(key('fast'), 'x10')
            hint(key('reset'), 'reset')
            if menu.focus == 'items' then hint(key('accept') .. '/' .. key('search'), 'search')
            else hint(key('accept'), 'type / open'); hint(key('back'), 'close'); hint(key('search'), 'search') end
        end
    elseif menu.page == 2 then
        for n, name in ipairs(menu.presets) do
            local here = n == menu.preset_row
            local y = TOP + (n - 1) * 26
            if y < PANEL_H - 130 then
                local label = name
                if name == preset_name then
                    local count = 0
                    for _ in pairs(overrides) do count = count + 1 end
                    label = name .. '   (' .. L('active') .. ', ' .. count .. ' ' .. L('values') .. ')'
                end
                row(label, 24, y, 620, here, here and menu.mode == 'list', 58,
                    pick(menu.preset_row, n, function(k) menu.preset_row = k end))
                if here then
                    local ax = 660
                    for a, action in ipairs(MENU_PRESET_ACTIONS) do
                        local label_a = L(action)
                        area(ax, y, 24 + menu_cells(label_a) * 10, 24, function()
                            menu.preset_action, menu.click_accept = a, true
                        end)
                        if a == menu.preset_action then yellow('[' .. label_a .. ']', ax, y + 3, 17)
                        else gray(label_a, ax + 6, y + 3, 17) end
                        ax = ax + 30 + menu_cells(label_a) * 10
                    end
                end
            end
        end
        for n, label in ipairs({ '+ New preset (empty)', '+ New preset (copy of the active one)' }) do
            local index = #menu.presets + n
            local y = TOP + (index - 1) * 26
            if y < PANEL_H - 100 then row(L(label), 24, y, 620, index == menu.preset_row, index == menu.preset_row
                                          and menu.mode == 'list', 58,
                                          pick(menu.preset_row, index, function(k) menu.preset_row = k end)) end
        end
        if menu.box and menu.box.kind == 'name' then
            rect(16, PANEL_H - 104, 520, 24, 255, 255, 214, 0)
            if layers then text(L('Name') .. ': ' .. menu.box.text .. '_', 24, PANEL_H - 101, 17, 255, 0, 0, 0)
            else yellow(L('Name') .. ': ' .. menu.box.text .. '_', 24, PANEL_H - 101, 17) end
        elseif menu.ask then
            yellow(L('Delete the preset "%s"?   %s yes   %s no'):format(menu.ask.name, key('accept'), key('back')), 24,
                   PANEL_H - 101, 17)
        end
        if menu.mode == 'text' then
            hint(key('accept'), 'confirm'); hint(key('back'), 'cancel'); hint(menu.key_name('BACKSPACE'), 'delete a letter')
        else
            hint(key('up') .. '/' .. key('down'), 'move'); hint(key('left') .. '/' .. key('right'), 'action')
            hint(key('accept'), 'select')
        end
    elseif menu.page == 3 then
        local clash = menu_key_clash()
        for n, action in ipairs(MENU_ACTIONS) do
            local here = n == menu.key_row
            local y = TOP + (n - 1) * 26
            row(L(action[3]), 24, y, 760, here, here and menu.mode == 'list', 44,
                pick(menu.key_row, n, function(k) menu.key_row = k end))
            local bound = key(action[1])
            local dark = here and menu.mode == 'list' and layers
            if dark then text(menu.key_name(bound), 520, y + 3, 17, 255, 0, 0, 0)
            elseif bound == clash then yellow('! ' .. menu.key_name(bound), 520, y + 3, 17)
            else gray(menu.key_name(bound), 520, y + 3, 17) end
        end
        local y = TOP + #MENU_ACTIONS * 26
        local n = #MENU_ACTIONS + 1
        local state_text = menu.block_missing and L('not available in this game') or (menu.block and L('on') or L('off'))
        row(L('Block game input while the menu is open'), 24, y, 760, n == menu.key_row, n == menu.key_row
            and menu.mode == 'list', 44, pick(menu.key_row, n, function(k) menu.key_row = k end))
        if n == menu.key_row and menu.mode == 'list' and layers then text(state_text, 520, y + 3, 17, 255, 0, 0, 0)
        else gray(state_text, 520, y + 3, 17) end
        gray(L(menu.block_failed and 'switched off: the game closed when this was tried'
               or 'the game gets no keys and no mouse'), 800, y + 5)
        row(L('Reset the keys'), 24, y + 26, 760, n + 1 == menu.key_row, n + 1 == menu.key_row and menu.mode == 'list', 44,
            pick(menu.key_row, n + 1, function(k) menu.key_row = k end))
        if menu.capture then
            yellow(L('Press the key for: %s   (%s cancels)'):format(L(menu.capture.label), key('back')), 24, PANEL_H - 101, 17)
        end
        hint(key('up') .. '/' .. key('down'), 'move'); hint(key('accept'), 'select')
    else
        local names = { 'English', menu.lang == 'zh' and L('Chinese (Simplified)') or 'Chinese (Simplified)' }
        for n, name in ipairs(names) do
            local here = n == menu.lang_row
            local chosen = (n == 1) == (menu.lang == 'en')
            row(name .. (chosen and '   *' or ''), 24, TOP + (n - 1) * 26, 620, here, here, 58,
                pick(menu.lang_row, n, function(k) menu.lang_row = k end))
        end
        if menu.zh_failed then gray(L('Chinese is switched off: the game stopped when it was drawn'), 660, TOP + 26 + 5)
        elseif not menu.zh_font then gray(L('no font of the game can draw Chinese'), 660, TOP + 26 + 5) end
        hint(key('up') .. '/' .. key('down'), 'move'); hint(key('accept'), 'select')
    end
    hint(key('toggle'), 'close')
    if menu.note and now and now < (menu.note_until or 0) then
        yellow('! ' .. menu_clip(menu.note, 150), 20, PANEL_H - 76)
    else
        menu.note = nil
    end
    gray(menu_clip(menu.message(state.verdict), 110), 20, PANEL_H - 52)
    if menu.saved_at then gray(L('Saved to') .. ' "' .. tostring(preset_name) .. '"', 900, PANEL_H - 52) end
    gray(menu_clip(table.concat(hints, '    '), 150), 20, PANEL_H - 26)
    -- the pointer, and what a click does. Only while the lists are in charge: a box that is being typed
    -- into, a key that is being chosen and a question take no clicks.
    local button = A.key_down(0x01)
    if mouse and menu.mouse_used then
        rect(mouse.x - 1, mouse.y - 1, 12, 12, 255, 0, 0, 0, 903)
        rect(mouse.x, mouse.y, 10, 10, 255, 255, 214, 0, 904)
        if button and not menu.mouse_down and menu.mode == 'list' then
            local hit = nil
            for _, h in ipairs(hot) do
                if mouse.x >= h[1] and mouse.x < h[1] + h[3] and mouse.y >= h[2] and mouse.y < h[2] + h[4] then hit = h end
            end
            if hit then hit[5]() end
        end
    end
    menu.mouse_down = button
    if not menu_trail.drawn then
        menu_trail.drawn = true
        log('menu: first frame drawn')
        flush_log()
    end
    if menu.box and not menu_trail['box ' .. menu.box.kind] then
        menu_trail['box ' .. menu.box.kind] = true
        log('menu: the ' .. menu.box.kind .. ' box: first frame drawn')
        flush_log()
    end
    if menu.lang == 'zh' and menu.zh_trying then
        menu.zh_frames = (menu.zh_frames or 0) + 1
        if menu.zh_frames >= 60 then
            menu.zh_trying, menu.lang_saved = nil, 'zh'
            pcall(menu_settings_save)
            log('menu: Chinese drawn for 60 frames: kept')
        end
    end
end

-- once per frame
local function menu_tick()
    if not menu.loaded then pcall(menu_load) end
    local now = A.now()
    if menu.settings_unsaved and now - (menu.settings_tried or 0) > 0.5 then
        menu.settings_tried = now
        pcall(menu_settings_save)
    end
    local down = A.key_down(KEY_VK[menu_bound('toggle')] or config.menu_vk)
    local toggled = down and not menu.toggle_down
    menu.toggle_down = down
    if toggled and not A.game_in_front() then toggled = false end
    -- while a key is being chosen, or a box is typed into, the menu key is a key like any other
    if toggled and menu.open and menu.mode == 'capture' then toggled = false end
    if toggled then
        if menu.open then
            menu_close(now)
        else
            local ok, started, why = pcall(menu_start)
            if ok and started then
                menu.open, menu.state = true, 'open'
            else
                menu.state = 'failed: ' .. tostring(why or started)
                log('menu: ' .. menu.state)
            end
        end
    end
    -- (only ever set while the menu is open)
    if menu.keys_blocked then menu.block_watch(now) end
    if not menu.open then return end
    local ok, why = pcall(function()
        menu_input(now)
        menu_draw(now)
    end)
    if not ok then
        log('menu: closed after an error: ' .. tostring(why))
        menu_close(now)
        menu.state = 'failed: ' .. tostring(why)
    end
end


local function tick()
    state.frame = state.frame + 1
    if state.frame < START_FRAME then return end
    menu_tick()
    -- the reload key: one key-state read per frame; the window is only checked on a press
    local down = A.key_down(config.reload_vk)
    if down and not key_was_down and A.game_in_front() then
        local pressed_at = A.now()
        if pressed_at - last_key_reload >= RELOAD_DEBOUNCE then
            last_key_reload = pressed_at
            log('reload key pressed')
            request_reload()
        end
    end
    key_was_down = down
    if state.frame % STEP_EVERY ~= 0 then return end
    local now = A.now()
    if config.auto_reload > 0 and now >= wake.config_check_at and build.state == 'verified' then
        wake.config_check_at = now + config.auto_reload
        local text = read_file(MOD.config)
        if text ~= nil and text ~= config.text then
            log('config.txt changed on disk')
            request_reload()
        end
    end
    if now < wake.at then return end
    if not worker then worker = coroutine.create(worker_main) end
    deadline = now + FRAME_BUDGET
    local ok, why = coroutine.resume(worker)
    local cost = A.now() - now
    state.busy_frames, state.busy_seconds = state.busy_frames + 1, state.busy_seconds + cost
    if cost > state.worst_frame then state.worst_frame, state.worst_step = cost, tostring(state.step) end
    if not ok then
        state.errors = state.errors + 1
        log('worker failed: ' .. tostring(why))
        worker = nil
        if state.errors >= 5 then
            state.phase, state.failure = 'gave_up', 'too many errors, last: ' .. tostring(why)
            state.retired = true
            write_status(true)
        else
            wake.at = A.now() + 5
            write_status(true)
        end
    end
end

-- ---------------------------------------------------------------- API (for a future UI)
-- Read access to everything the engine knows, and a way to change values without the file.
state.api = {
    version = 1,
    categories = function()
        local seen, list = {}, {}
        for index = 0, #ITEMS do
            local item = ITEMS[index]
            if item and not seen[item.category] then seen[item.category] = true; list[#list + 1] = item.category end
        end
        return list
    end,
    items = function(category)
        local list = {}
        for index = 0, #ITEMS do
            local item = ITEMS[index]
            if item and item.category == category then list[#list + 1] = item.name end
        end
        return list
    end,
    -- -> list of { id, game, current, min, max, integer, editable, shared_with }
    stats = function(category, name)
        local item = ITEM_BY_NAME[tostring(category) .. ':' .. tostring(name):lower()]
        if not item then return nil end
        local list = {}
        for _, stat in ipairs(item.stat_order) do
            local entry, range = item.stats[stat], RANGES[stat]
            local want = desired[entry.field.key]
            list[#list + 1] = { id = stat, game = entry.field.stock, current = want and want.value or entry.field.stock,
                                min = range.min, max = range.max, integer = range.integer,
                                editable = not entry.attachment, shared_with = #entry.field.users - 1 }
        end
        return list
    end,
    -- expression: '120', '150%', '+15', or nil to drop the override
    set = function(category, name, stat, expression)
        overrides[tostring(category):lower() .. ':' .. tostring(name):lower() .. ':' .. tostring(stat):lower()] =
            expression ~= nil and tostring(expression) or nil
        request_reload()
    end,
    reload = request_reload,
    verdict = function() return state.verdict end,
    close_menu = function() if menu.open then menu_close(A.now()) end end,
    hook_code = function(flag, next_hook) return A.hook_code(flag, next_hook) end,
}

-- ---------------------------------------------------------------- startup
log(MOD.title .. ' v' .. MOD.version)
local api_ok, api_failure = pcall(function()
    assert(ffi_ok and ffi, 'LuaJIT FFI is unavailable')
    assert(ffi.abi('64bit'), 'Windows x64 is required')
    A = build_api()
end)
if not api_ok then A = nil end
local ok, failure = pcall(function()
    local loader = rawget(_G, 'CowboyBingusModLoader')
    if type(loader) == 'table' and tonumber(loader.api) and tonumber(loader.api) < 1 then
        error('Bingus Shared Loader is too old (API ' .. tostring(loader.api) .. '); v15 or newer is required', 0)
    end
    if not api_ok then error(tostring(api_failure), 0) end
    -- decoder and encoder must agree on known bit patterns before anything may be written
    for _, case in ipairs({ { 0x3F800000, 1.0 }, { 0x43AF0000, 350.0 }, { 0x42C80000, 100.0 },
                            { 0x3E800000, 0.25 }, { 0xBF000000, -0.5 }, { 0x44610000, 900.0 } }) do
        if bits_to_f32(case[1]) ~= case[2] or A.f32_bits(case[2]) ~= case[1] then
            error('float self-test failed', 0)
        end
    end
    if type(rawget(_G, 'update')) ~= 'function' then error('the game update hook is unavailable', 0) end
end)

if not ok then
    state.phase, state.failure = 'gave_up', tostring(failure)
    log('startup failed: ' .. tostring(failure))
    print('[' .. MOD.global .. '] ' .. tostring(failure))
    write_file(MOD.status, 'FAILED - ' .. tostring(failure) .. '\r\n' .. MOD.title .. ' v' .. MOD.version .. '\r\n')
    flush_log()
    return
end

log('armed; folder ' .. tostring(ensure_out_dir()))
write_file(MOD.status, 'WAITING - starting (nothing written yet)\r\n' .. MOD.title .. ' v' .. MOD.version .. '\r\n')
flush_log()

-- Guarded hook: we never cut other addons out of the update chain.
local original_update = update
local my_update
my_update = function(...)
    if not state.retired then
        local tick_ok, why = pcall(tick)
        if not tick_ok then
            state.errors = state.errors + 1
            log('tick: ' .. tostring(why))
            if state.errors >= 20 then state.retired = true end
        end
    end
    return original_update(...)
end
update = my_update
